"""Generate Flashback (Moulberry) editor-state / keyframes for automatic cinematic B-roll.

Everything here mirrors what the decompiled mod (v0.39.10, MC 1.21.11) reads and writes:

* ``.minecraft/flashback/editor_states/<replay uuid>.json``  <- ``EditorState`` serialised with
  ``FlashbackGson.COMPRESSED`` (Gson). The file name is the ``uuid`` from the replay's metadata.json.
  ``Flashback.openReplayWorld`` calls ``EditorStateManager.get(uuid)`` which loads it, so writing this
  file *before* the replay is opened is how keyframes are injected without touching the GUI.
* Timeline unit = **replay ticks (20/s)**; keyframes live in ``scene.keyframeTracks[i].keyframesByTick``
  keyed by tick-as-string. One scene == one shot (own tracks + own export range).
* Camera conventions (verified from ``KeyframeChangeCameraPosition*`` / ``KeyframeChangeTrackEntity``):
    - ``camera`` keyframe ``position`` is the *feet* position of the camera entity; the eye is +1.62.
    - ``camera_orbit``: camera eye = center - look(yaw,pitch) * distance, facing (yaw,pitch).
      ``center`` is the world point to look at (use eye height of the subject).
    - MC angles: yaw 0 = +Z (south), 90 = -X (west); pitch +90 = straight down.

Public API
----------
Shot templates (all return a :class:`Shot`):  ``orbit``, ``drone_pullup``, ``push_in``, ``flyby``,
``track_follow``, ``timelapse``.   Build a document with :func:`build_state`, validate with
:func:`validate_state`, write with :func:`write_state`, plan automatically with :func:`auto_shots`.

CLI demo:  python -m mcstudio.flashback_keyframes <replay.zip> [--out DIR]
"""
from __future__ import annotations

import copy
import json
import math
import re
import uuid as _uuid
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Iterable, Sequence

EYE_HEIGHT = 1.62  # standing player/spectator camera eye height (Entity.getEyeHeight)

# ---------------------------------------------------------------------------
# Schema constants (from KeyframeType.id(), Keyframe.TypeAdapter, enums)
# ---------------------------------------------------------------------------
TRACK_TYPES = {
    # track id (KeyframeType.id())   -> keyframe "type" string used inside the keyframe object
    "CAMERA": "camera",
    "CAMERA_ORBIT": "camera_orbit",
    "TRACK_ENTITY": "track_entity",
    "CAMERA_SHAKE": "camera_shake",
    "FOV": "fov",
    "SPEED": "tickrate",
    "TIMELAPSE": "timelapse",
    "TIME_OF_DAY": "time",
    "FREEZE": "freeze",
    "BLOCK_OVERRIDE": "block_override",
    "AUDIO": "audio",
}
INTERPOLATIONS = ("SMOOTH", "LINEAR", "EASE_IN", "EASE_OUT", "EASE_IN_OUT", "HOLD", "HERMITE")
BODY_PARTS = ("HEAD", "BODY", "ROOT")
WEATHER = ("NONE", "CLEAR", "OVERCAST", "RAINING", "SNOWING", "THUNDERING")
SIZING = ("KEEP_ASPECT_RATIO", "CHANGE_ASPECT_RATIO", "FILL", "UNDERLAY")
ASPECTS = ("ASPECT_16_9", "ASPECT_9_16", "ASPECT_240_1", "ASPECT_1_1", "ASPECT_4_3", "ASPECT_3_2")
GLOWING = ("DEFAULT", "FORCE_GLOW", "FORCE_NO_GLOW")
VIDEO_CONTAINERS = ("MP4", "MKV", "AVI", "MOV", "PNG_SEQUENCE", "WEBP", "WEBM", "GIF")
VIDEO_CODECS = ("H264", "H265", "AV1", "VP9", "PRO_RES", "QUICK_TIME", "WEBP", "GIF")

_UUID_RE = re.compile(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$")

# ReplayVisuals field -> (python type tag, default). Source: com.moulberry.flashback.visuals.ReplayVisuals
VISUALS_FIELDS: dict[str, tuple[str, object]] = {
    "showChat": ("bool", False), "showBossBar": ("bool", False), "showTitleText": ("bool", False),
    "showScoreboard": ("bool", False), "showActionBar": ("bool", False), "showHotbar": ("bool", True),
    "renderBlocks": ("bool", True), "renderEntities": ("bool", True), "renderPlayers": ("bool", True),
    "renderParticles": ("bool", True), "renderSky": ("bool", True),
    "skyColour": ("f3", [0.0, 1.0, 0.0]),
    "renderNametags": ("bool", True), "renderBeaconBeams": ("bool", True),
    "overrideFog": ("bool", False), "overrideFogStart": ("float", 0.0), "overrideFogEnd": ("float", 256.0),
    "overrideFogColour": ("bool", False), "fogColour": ("f3", [0.0, 1.0, 0.0]),
    "overrideFov": ("bool", False), "overrideFovAmount": ("float", -1.0),
    "overrideCameraShake": ("bool", False), "cameraShakeSplitParams": ("bool", False),
    "cameraShakeYFrequency": ("float", 1.0), "cameraShakeYAmplitude": ("float", 1.0),
    "cameraShakeXFrequency": ("float", 1.0), "cameraShakeXAmplitude": ("float", 1.0),
    "overrideRoll": ("bool", False), "overrideRollAmount": ("float", 0.0),
    "overrideWeatherMode": ("enum:WEATHER", "NONE"),
    "overrideTimeOfDay": ("long", -1),
    "overrideNightVision": ("bool", False),
    "ruleOfThirdsGuide": ("bool", False), "centerGuide": ("bool", False), "cameraPath": ("bool", True),
    "sizing": ("enum:SIZING", "KEEP_ASPECT_RATIO"), "changeAspectRatio": ("enum:ASPECTS", "ASPECT_16_9"),
    "disableServerResourcePack": ("bool", False),
}


def default_visuals() -> dict:
    return {k: copy.deepcopy(v[1]) for k, v in VISUALS_FIELDS.items()}


@dataclass
class Visuals:
    """High level visual overrides applied to the whole editor state (``replayVisuals``)."""

    hide_nametags: bool = True
    hide_hud: bool = True           # chat/boss bar/title/scoreboard/action bar/hotbar off
    night_vision: bool = False
    time_of_day: int | None = None  # 0..24000 (6000 = noon, 18000 = midnight); None = leave replay time
    weather: str = "NONE"
    fov: float | None = None        # global override (degrees); None = keep the in-game FOV
    camera_path_overlay: bool = False  # the editor's camera-path gizmo (never wanted in a render)
    render_particles: bool = True
    aspect: str | None = None       # e.g. "ASPECT_9_16" for shorts -> sizing CHANGE_ASPECT_RATIO
    extra: dict = field(default_factory=dict)  # raw replayVisuals overrides

    def to_dict(self) -> dict:
        d = default_visuals()
        if self.hide_nametags:
            d["renderNametags"] = False
        if self.hide_hud:
            for k in ("showChat", "showBossBar", "showTitleText", "showScoreboard", "showActionBar", "showHotbar"):
                d[k] = False
        d["overrideNightVision"] = bool(self.night_vision)
        if self.time_of_day is not None:
            d["overrideTimeOfDay"] = int(self.time_of_day)
        d["overrideWeatherMode"] = self.weather
        if self.fov is not None:
            d["overrideFov"] = True
            d["overrideFovAmount"] = float(self.fov)
        d["cameraPath"] = bool(self.camera_path_overlay)
        d["renderParticles"] = bool(self.render_particles)
        if self.aspect:
            d["sizing"] = "CHANGE_ASPECT_RATIO"
            d["changeAspectRatio"] = self.aspect
        d.update(self.extra)
        return d


# ---------------------------------------------------------------------------
# Keyframe constructors (dict form == what Keyframe.TypeAdapter serialises)
# ---------------------------------------------------------------------------
def _f(x):
    return float(x)


def vec3(v) -> list[float]:
    x, y, z = v
    return [_f(x), _f(y), _f(z)]


def camera_kf(feet_pos, yaw: float, pitch: float, roll: float = 0.0, interp: str = "SMOOTH") -> dict:
    return {"position": vec3(feet_pos), "yaw": _f(yaw), "pitch": _f(pitch), "roll": _f(roll),
            "type": "camera", "interpolation_type": interp}


def camera_eye_kf(eye_pos, yaw, pitch, roll=0.0, interp="SMOOTH") -> dict:
    """Camera keyframe from a desired *eye* position (converts to feet position)."""
    x, y, z = eye_pos
    return camera_kf((x, y - EYE_HEIGHT, z), yaw, pitch, roll, interp)


def orbit_kf(center, distance: float, yaw: float, pitch: float, interp: str = "SMOOTH") -> dict:
    return {"center": vec3(center), "distance": _f(distance), "yaw": _f(yaw), "pitch": _f(pitch),
            "type": "camera_orbit", "interpolation_type": interp}


def track_entity_kf(target_uuid: str, part: str = "BODY", yaw_offset: float = 0.0, pitch_offset: float = 0.0,
                    position_offset=(0, 0, 0), view_offset=(0, 0, 0), roll: float = 0.0,
                    interp: str = "SMOOTH") -> dict:
    return {"target": target_uuid, "bodyPart": part, "yawOffset": _f(yaw_offset), "pitchOffset": _f(pitch_offset),
            "positionOffset": vec3(position_offset), "viewOffset": vec3(view_offset),
            "type": "track_entity", "roll": _f(roll), "interpolation_type": interp}


def fov_kf(fov: float, interp: str = "SMOOTH") -> dict:
    return {"fov": _f(fov), "type": "fov", "interpolation_type": interp}


def tickrate_kf(tickrate: float, interp: str = "SMOOTH") -> dict:
    """Speed track. ``tickrate`` is replay ticks per real second: 20 = 1x, 40 = 2x, 10 = 0.5x."""
    return {"tickrate": _f(tickrate), "type": "tickrate", "interpolation_type": interp}


def freeze_kf(frozen: bool, delay: int = 0, interp: str = "HOLD") -> dict:
    return {"freeze": bool(frozen), "freezeDelay": int(delay), "type": "freeze", "interpolation_type": interp}


def timelapse_kf(video_ticks: int) -> dict:
    """Timelapse keyframe. Placed at timeline tick K it says 'output video time == video_ticks (20/s)'.
    Speed between two keyframes = (K2-K1)/(T2-T1)*20 replay ticks/s (KeyframeTrack.tryApplyKeyframesTimelapse).
    No interpolation_type is serialised (always LINEAR)."""
    return {"ticks": int(video_ticks), "type": "timelapse"}


def time_of_day_kf(time: int, interp: str = "SMOOTH") -> dict:
    return {"time": int(time), "type": "time", "interpolation_type": interp}


def shake_kf(freq_x=1.0, amp_x=1.0, freq_y=1.0, amp_y=1.0, split=False, interp="SMOOTH") -> dict:
    d = {"frequencyX": _f(freq_x), "amplitudeX": _f(amp_x), "frequencyY": _f(freq_y), "amplitudeY": _f(amp_y)}
    if split:
        d["splitParams"] = True
    d.update({"type": "camera_shake", "interpolation_type": interp})
    return d


# ---------------------------------------------------------------------------
# Document model
# ---------------------------------------------------------------------------
@dataclass
class Track:
    type: str                                   # key of TRACK_TYPES
    keyframes: dict[int, dict] = field(default_factory=dict)
    enabled: bool = True
    custom_name: str | None = None
    custom_colour: int = 0

    def to_dict(self) -> dict:
        d = {"keyframeType": self.type,
             "keyframesByTick": {str(k): v for k, v in sorted(self.keyframes.items())},
             "enabled": self.enabled}
        if self.custom_name:
            d["customName"] = self.custom_name
        d["customColour"] = self.custom_colour
        return d


@dataclass
class Shot:
    """One shot == one editor scene. ``start``/``end`` are replay ticks (export range)."""

    name: str
    kind: str
    start: int
    end: int
    tracks: list[Track]
    note: str = ""
    params: dict = field(default_factory=dict)

    @property
    def seconds(self) -> float:
        return (self.end - self.start) / 20.0

    def to_scene(self) -> dict:
        return {
            "name": self.name,
            "keyframeTracks": [t.to_dict() for t in self.tracks],
            "exportStartTicks": int(self.start),
            "exportEndTicks": int(self.end),
            "history": {"entries": [], "position": 0},
        }


def empty_state(replay_path: str | None = None, visuals: Visuals | None = None) -> dict:
    """A blank EditorState dict, identical in shape to what Flashback itself writes."""
    return {
        "replayVisuals": (visuals or Visuals()).to_dict(),
        "sceneLock": {},
        "scenes": [],
        "sceneIndex": 0,
        "zoomMin": 0.0,
        "zoomMax": 1.0,
        "usedByPaths": [str(replay_path)] if replay_path else [],
        "hideDuringExport": [],
        "hideAllSpectators": False,
        "muteVoice": [],
        "hideNametags": [],
        "skinOverride": {},
        "skinOverrideFromFile": {},
        "nameOverride": {},
        "glowingOverride": {},
        "hideTeamPrefix": [],
        "hideTeamSuffix": [],
        "hideBelowName": [],
        "hideCape": [],
        "filteredEntities": [],
        "filteredParticles": [],
        "hiddenEquipment": {},
        "hiddenModelParts": {},
    }


def build_state(shots: Sequence[Shot], visuals: Visuals | None = None, replay_path: str | Path | None = None,
                hide_entities: Iterable[str] = (), scene_index: int = 0) -> dict:
    """EditorState dict with one scene per shot."""
    st = empty_state(str(replay_path) if replay_path else None, visuals)
    st["scenes"] = [s.to_scene() for s in shots]
    if not st["scenes"]:  # Flashback always wants >= 1 scene
        st["scenes"] = [{"name": "Scene 1", "keyframeTracks": [], "exportStartTicks": -1, "exportEndTicks": -1,
                         "history": {"entries": [], "position": 0}}]
    st["sceneIndex"] = scene_index
    st["hideDuringExport"] = [str(u) for u in hide_entities]
    return st


def dumps_state(state: dict) -> str:
    """Compact JSON like ``FlashbackGson.COMPRESSED`` (no spaces, doubles keep '.0')."""
    return json.dumps(state, separators=(",", ":"), ensure_ascii=False)


def write_state(state: dict, replay_uuid: str, folder: str | Path) -> Path:
    """Write ``<folder>/<replay_uuid>.json``. ``folder`` must be ``<.minecraft>/flashback/editor_states``
    for Flashback to pick it up -- this function does not default to it on purpose.
    The previous file (if any) is kept as ``.json.old`` exactly like EditorStateManager.save() does."""
    errs = validate_state(state)
    if errs:
        raise ValueError("invalid editor state:\n  " + "\n  ".join(errs))
    folder = Path(folder)
    folder.mkdir(parents=True, exist_ok=True)
    p = folder / f"{replay_uuid}.json"
    if p.exists():
        p.replace(folder / f"{replay_uuid}.json.old")
    p.write_text(dumps_state(state), encoding="utf-8")
    return p


# ---------------------------------------------------------------------------
# Validation == the rules the Gson TypeAdapters/constructors enforce on load
# ---------------------------------------------------------------------------
def _is_num(x):
    return isinstance(x, (int, float)) and not isinstance(x, bool)


def _vec3_ok(v):
    return isinstance(v, list) and len(v) == 3 and all(_is_num(c) for c in v)


def validate_keyframe(track_type: str, kf: dict, where: str) -> list[str]:
    errs: list[str] = []
    want = TRACK_TYPES.get(track_type)
    if want is None:
        return [f"{where}: unknown track type {track_type!r}"]
    if not isinstance(kf, dict) or kf.get("type") != want:
        return [f"{where}: keyframe type {kf.get('type') if isinstance(kf, dict) else kf!r} != {want!r} "
                f"(Keyframe.TypeAdapter + ClassCastException when a track mixes types)"]
    it = kf.get("interpolation_type")
    if it is not None and it not in INTERPOLATIONS:
        errs.append(f"{where}: bad interpolation_type {it!r}")
    if track_type in ("TIMELAPSE", "BLOCK_OVERRIDE", "AUDIO"):
        pass
    req: dict[str, str] = {
        "CAMERA": "position",                       # yaw/pitch/roll default to 0
        "CAMERA_ORBIT": "center,distance,yaw,pitch",
        "TRACK_ENTITY": "target,bodyPart,yawOffset,pitchOffset",
        "CAMERA_SHAKE": "frequencyX,amplitudeX,frequencyY,amplitudeY",
        "FOV": "fov",
        "SPEED": "tickrate",
        "TIMELAPSE": "ticks",
        "TIME_OF_DAY": "time",
        "FREEZE": "freeze",
    }.get(track_type, "")
    for k in filter(None, req.split(",")):
        if k not in kf:
            errs.append(f"{where}: missing required field {k!r} (getAs*() on null -> NPE on load)")
    for k in ("position", "center", "positionOffset", "viewOffset"):
        if k in kf and kf[k] is not None and not _vec3_ok(kf[k]):
            errs.append(f"{where}: {k} must be a 3-number array (Vector3dTypeAdapater), got {kf[k]!r}")
    for k in ("yaw", "pitch", "roll", "distance", "yawOffset", "pitchOffset", "fov", "tickrate",
              "frequencyX", "amplitudeX", "frequencyY", "amplitudeY"):
        if k in kf and not _is_num(kf[k]):
            errs.append(f"{where}: {k} must be a number")
    for k in ("ticks", "time", "freezeDelay"):
        if k in kf and (not isinstance(kf[k], int) or isinstance(kf[k], bool)):
            errs.append(f"{where}: {k} must be an int (getAsInt)")
    if "freeze" in kf and not isinstance(kf["freeze"], bool):
        errs.append(f"{where}: freeze must be bool")
    if track_type == "TRACK_ENTITY":
        if not (isinstance(kf.get("target"), str) and _UUID_RE.match(kf["target"])):
            errs.append(f"{where}: target must be a UUID string")
        if kf.get("bodyPart") not in BODY_PARTS:
            errs.append(f"{where}: bodyPart must be one of {BODY_PARTS}")
    if track_type == "FOV" and _is_num(kf.get("fov")) and not (1.0 <= kf["fov"] <= 110.0):
        errs.append(f"{where}: fov {kf['fov']} outside editor slider range 1..110 (not enforced by loader)")
    if track_type == "SPEED" and _is_num(kf.get("tickrate")) and kf["tickrate"] <= 0:
        errs.append(f"{where}: tickrate must be > 0 (clamped to 0.001 at runtime)")
    return errs


def validate_state(state: dict) -> list[str]:
    """Return a list of problems (empty == the loader would accept it). Mirrors EditorState/EditorScene/
    KeyframeTrack/Keyframe deserialisation. Note: EditorScene & KeyframeTrack have no no-arg constructor, so Gson
    allocates them with Unsafe and *skips field initialisers* -> every field must be present in the JSON."""
    errs: list[str] = []
    if not isinstance(state, dict):
        return ["state is not an object"]
    rv = state.get("replayVisuals")
    if not isinstance(rv, dict):
        errs.append("replayVisuals missing")
    else:
        for k, (tag, _d) in VISUALS_FIELDS.items():
            if k not in rv:
                continue  # EditorState has a no-arg ctor -> ReplayVisuals initialiser keeps default
            v = rv[k]
            ok = {
                "bool": isinstance(v, bool),
                "float": _is_num(v),
                "long": isinstance(v, int) and not isinstance(v, bool),
                "f3": isinstance(v, list) and len(v) == 3 and all(_is_num(c) for c in v),
            }.get(tag)
            if ok is None and tag.startswith("enum:"):
                ok = v in {"WEATHER": WEATHER, "SIZING": SIZING, "ASPECTS": ASPECTS}[tag.split(":")[1]]
            if not ok:
                errs.append(f"replayVisuals.{k}: bad value {v!r} ({tag})")
        for k in rv:
            if k not in VISUALS_FIELDS:
                errs.append(f"replayVisuals.{k}: unknown field (Gson ignores it)")
    scenes = state.get("scenes")
    if not isinstance(scenes, list) or not scenes:
        errs.append("scenes must be a non-empty list (EditorState.currentScene() = scenes.get(sceneIndex))")
        scenes = []
    si = state.get("sceneIndex", 0)
    if not isinstance(si, int) or not (0 <= si < max(1, len(scenes))):
        errs.append(f"sceneIndex {si!r} out of range")
    for i, sc in enumerate(scenes):
        w = f"scenes[{i}]"
        if not isinstance(sc.get("name"), str):
            errs.append(f"{w}.name missing")
        for k in ("exportStartTicks", "exportEndTicks"):
            if not isinstance(sc.get(k), int):
                errs.append(f"{w}.{k} must be int (-1 = unset)")
        h = sc.get("history")
        if not (isinstance(h, dict) and isinstance(h.get("entries"), list) and isinstance(h.get("position"), int)):
            errs.append(f"{w}.history must be {{entries:[], position:int}} (null after Unsafe alloc otherwise)")
        tracks = sc.get("keyframeTracks")
        if not isinstance(tracks, list):
            errs.append(f"{w}.keyframeTracks must be a list")
            continue
        cam_like = {"CAMERA", "CAMERA_ORBIT", "TRACK_ENTITY"}
        for j, tr in enumerate(tracks):
            tw = f"{w}.keyframeTracks[{j}]"
            tt = tr.get("keyframeType")
            if tt not in TRACK_TYPES:
                errs.append(f"{tw}.keyframeType {tt!r} unknown (KeyframeRegistry.TypeAdapter requireNonNull)")
                continue
            if not isinstance(tr.get("enabled"), bool):
                errs.append(f"{tw}.enabled must be present (Unsafe alloc defaults it to false -> track silently off)")
            if not isinstance(tr.get("customColour", 0), int):
                errs.append(f"{tw}.customColour must be int")
            kfs = tr.get("keyframesByTick")
            if not isinstance(kfs, dict):
                errs.append(f"{tw}.keyframesByTick must be an object (null -> NPE)")
                continue
            for tk, kf in kfs.items():
                if not re.fullmatch(r"-?\d+", str(tk)):
                    errs.append(f"{tw}: tick key {tk!r} not an int")
                elif int(tk) < 0:
                    errs.append(f"{tw}: negative tick {tk}")
                errs += validate_keyframe(tt, kf, f"{tw}@{tk}")
            if tt == "TIMELAPSE":
                ks = sorted(int(k) for k in kfs)
                for a, b in zip(ks, ks[1:]):
                    if kfs[str(b)]["ticks"] <= kfs[str(a)]["ticks"]:
                        errs.append(f"{tw}: timelapse ticks must strictly increase ({a}->{b})")
        tt_cam = [t for t in tracks if t.get("keyframeType") in cam_like and t.get("enabled") and t.get("keyframesByTick")]
        if len(tt_cam) > 1:
            errs.append(f"{w}: {len(tt_cam)} enabled camera-type tracks; later tracks override earlier ones "
                        f"(EditorState.applyKeyframes applies each change class once, last applyCameraPosition wins)")
    for k in ("usedByPaths", "hideDuringExport", "muteVoice", "hideNametags", "hideTeamPrefix", "hideTeamSuffix",
              "hideBelowName", "hideCape", "filteredEntities", "filteredParticles"):
        if k in state and not isinstance(state[k], list):
            errs.append(f"{k} must be a list")
    for k in ("hideDuringExport", "muteVoice", "hideNametags", "hideTeamPrefix", "hideTeamSuffix", "hideBelowName",
              "hideCape"):
        for u in state.get(k, []):
            if not (isinstance(u, str) and _UUID_RE.match(u)):
                errs.append(f"{k}: {u!r} not a UUID")
    for k in ("skinOverride", "skinOverrideFromFile", "nameOverride", "glowingOverride", "hiddenEquipment",
              "hiddenModelParts"):
        if k in state and not isinstance(state[k], dict):
            errs.append(f"{k} must be an object")
    for u, g in state.get("glowingOverride", {}).items():
        if g not in GLOWING:
            errs.append(f"glowingOverride[{u}] bad enum {g!r}")
    return errs


def roundtrip_check(state: dict) -> list[str]:
    """Serialise -> parse -> serialise again; must be byte-identical (what Gson does on load+autosave)."""
    errs = validate_state(state)
    s1 = dumps_state(state)
    s2 = dumps_state(json.loads(s1))
    if s1 != s2:
        errs.append("JSON round trip is not stable")
    return errs


# ---------------------------------------------------------------------------
# Port of the runtime evaluation (KeyframeTrack.createKeyframeChange) for previews/self-checks.
# Supports CAMERA / CAMERA_ORBIT / FOV with SMOOTH / LINEAR / HOLD / EASE_*  (no speed tracks).
# ---------------------------------------------------------------------------
def _wrap180(a):  # Mth.wrapDegrees
    a = a % 360.0
    if a >= 180.0:
        a -= 360.0
    if a < -180.0:
        a += 360.0
    return a


def _lerp(a, b, t):
    return a + (b - a) * t


def _cr_core(p, tj, t, time1, time2, time3, lerp=_lerp):
    averageTj = (tj[0] + tj[1] + tj[2]) / 3.0
    if averageTj == 0.0:
        return None
    relation = (time3 / 3.0) / averageTj

    def dt(tjk, span, ok):
        if not ok:
            return 0.0
        f = tjk * relation / span
        f = max(0.4, min(2.5, f))
        return tjk * relation / f

    d1 = dt(tj[0], time1, time1 > 0)
    d2 = dt(tj[1], time2 - time1, time2 - time1 > 0)
    d3 = dt(tj[2], time3 - time2, time3 - time2 > 0)
    t0 = 0.0
    t1 = t0 + d1
    t2 = t1 + d2
    t3 = t2 + d3
    tt = t1 + (t2 - t1) * t
    a1 = lerp(p[0], p[1], 0.5 if t0 == t1 else (tt - t0) / (t1 - t0))
    a2 = lerp(p[1], p[2], 0.5 if t1 == t2 else (tt - t1) / (t2 - t1))
    a3 = lerp(p[2], p[3], 0.5 if t2 == t3 else (tt - t2) / (t3 - t2))
    b1 = lerp(a1, a2, 0.5 if t0 == t2 else (tt - t0) / (t2 - t0))
    b2 = lerp(a2, a3, 0.5 if t1 == t3 else (tt - t1) / (t3 - t1))
    return lerp(b1, b2, 0.5 if t1 == t2 else (tt - t1) / (t2 - t1))


def _cr_value(p0, p1, p2, p3, time1, time2, time3, amount):
    tj = [math.sqrt(abs(p0 - p1)), math.sqrt(abs(p1 - p2)), math.sqrt(abs(p2 - p3))]
    r = _cr_core([p0, p1, p2, p3], tj, amount, time1, time2, time3)
    return p1 if r is None else r


def _cr_degrees(p0, p1, p2, p3, time1, time2, time3, amount):
    d1, d2, d3 = _wrap180(p1 - p0), _wrap180(p2 - p1), _wrap180(p3 - p2)
    p0 = _wrap180(p0)
    p1 = p0 + d1
    p2 = p1 + d2
    p3 = p2 + d3
    tj = [math.sqrt(abs(_wrap180(p0 - p1))), math.sqrt(abs(_wrap180(p1 - p2))), math.sqrt(abs(_wrap180(p2 - p3)))]
    r = _cr_core([p0, p1, p2, p3], tj, amount, time1, time2, time3)
    return p1 if r is None else r


def _cr_position(P0, P1, P2, P3, time1, time2, time3, amount):
    def tjf(a, b):
        return ((b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2 + (b[2] - a[2]) ** 2) ** 0.25

    tj = [tjf(P0, P1), tjf(P1, P2), tjf(P2, P3)]
    if sum(tj) / 3.0 == 0.0:
        return list(P1)
    # same weights for all 3 axes => compute the knot times once, then blend per axis
    out = []
    for ax in range(3):
        r = _cr_core([P0[ax], P1[ax], P2[ax], P3[ax]], tj, amount, time1, time2, time3)
        out.append(P1[ax] if r is None else r)
    return out


def _sided(interp: str):
    return {"SMOOTH": ("SMOOTH", "SMOOTH"), "LINEAR": ("LINEAR", "LINEAR"), "EASE_IN": ("EASE", "LINEAR"),
            "EASE_OUT": ("LINEAR", "EASE"), "EASE_IN_OUT": ("EASE", "EASE"), "HOLD": ("HOLD", "HOLD"),
            "HERMITE": ("HERMITE", "HERMITE")}[interp]


def _sided_interp(left, right, amount):  # SidedInterpolationType.interpolate
    special = ("SMOOTH", "HERMITE")
    if left in special:
        if right in special:
            left = right = "LINEAR"
        else:
            left = right
    elif right in special:
        right = left
    if left == "HOLD":
        return 0.0
    if right == "HOLD":
        right = left
    if left == "LINEAR":
        if right == "LINEAR":
            return amount
        if right == "EASE":
            return 1.0 - (1.0 - amount) ** 3
    elif left == "EASE":
        if right == "LINEAR":
            return amount ** 3
        if right == "EASE":
            return 4 * amount ** 3 if amount < 0.5 else 1.0 - (-2.0 * amount + 2.0) ** 3 / 2.0
    raise ValueError("cannot interpolate")


def _fields(tt, kf):
    if tt == "CAMERA":
        return list(kf["position"]) + [kf.get("yaw", 0.0), kf.get("pitch", 0.0), kf.get("roll", 0.0)]
    if tt == "CAMERA_ORBIT":
        return list(kf["center"]) + [kf["distance"], kf["yaw"], kf["pitch"]]
    if tt == "FOV":
        return [1.0 / math.tan(math.radians(kf["fov"]) * 0.5)]
    raise NotImplementedError(tt)


def _lin_change(tt, a, b, t):
    out = [_lerp(x, y, t) for x, y in zip(a, b)]
    if tt == "CAMERA":  # linearAngle for yaw/pitch/roll
        for i in (3, 4, 5):
            d = _wrap180(b[i] - a[i])
            out[i] = a[i] + max(-180.0, min(180.0, d * t))
    return out


def _smooth_change(tt, k0, k1, k2, k3, t0, t1, t2, t3, amount):
    time1, time2, time3 = t1 - t0, t2 - t0, t3 - t0
    f = [_fields(tt, k) for k in (k0, k1, k2, k3)]
    if tt in ("CAMERA", "CAMERA_ORBIT"):
        pos = _cr_position(f[0][:3], f[1][:3], f[2][:3], f[3][:3], time1, time2, time3, amount)
        rest = []
        for i in range(3, len(f[0])):
            fn = _cr_degrees if (tt == "CAMERA") else _cr_value
            rest.append(fn(f[0][i], f[1][i], f[2][i], f[3][i], time1, time2, time3, amount))
        return pos + rest
    return [_cr_value(f[0][0], f[1][0], f[2][0], f[3][0], time1, time2, time3, amount)]


def evaluate_track(track: dict, tick: float):
    """Value of a serialised track at ``tick`` (floats list) or None. Raises on unsupported types/interps."""
    tt = track["keyframeType"]
    kfs = {int(k): v for k, v in track["keyframesByTick"].items()}
    if not kfs or not track.get("enabled", True):
        return None
    keys = sorted(kfs)
    lower = max((k for k in keys if k <= int(tick)), default=None)
    if lower is None:
        return None
    lk = kfs[lower]
    if tick == lower:
        return _fields(tt, lk)
    li = lk.get("interpolation_type") or "SMOOTH"
    left = _sided(li)[1]
    if left == "HOLD":
        return _fields(tt, lk)
    ceil = min((k for k in keys if k >= lower + 1), default=None)
    if ceil is None:
        return _fields(tt, lk) if int(tick) == lower else None
    ck = kfs[ceil]
    right = _sided(ck.get("interpolation_type") or "SMOOTH")[0]
    if right == "HOLD":
        right = left
    amount = (tick - lower) / (ceil - lower)
    if "HERMITE" in (left, right):
        raise NotImplementedError("HERMITE evaluation not ported")
    lc = rc = None
    if "SMOOTH" in (left, right):
        before = max((k for k in keys if k <= lower - 1), default=None)
        if before is None or (kfs[before].get("interpolation_type") == "HOLD"):
            before = lower
        after = min((k for k in keys if k >= ceil + 1), default=None)
        if after is None or ck.get("interpolation_type") == "HOLD":
            after = ceil
        sc = _smooth_change(tt, kfs[before], lk, ck, kfs[after], before, lower, ceil, after, amount)
        if left == "SMOOTH":
            lc = sc
        if right == "SMOOTH":
            rc = sc
    if lc is None or rc is None:
        adj = _sided_interp(left, right, amount)
        base = _fields(tt, lk)
        if adj != 0.0:
            base = _lin_change(tt, base, _fields(tt, ck), adj)
        lc = lc if lc is not None else base
        rc = rc if rc is not None else base
    return _lin_change(tt, lc, rc, amount)


def camera_pose(scene: dict, tick: float):
    """Camera eye position + yaw/pitch at ``tick`` for the scene's camera-type track (CAMERA or CAMERA_ORBIT)."""
    for tr in scene["keyframeTracks"]:
        if tr["keyframeType"] == "CAMERA":
            v = evaluate_track(tr, tick)
            if v:
                return (v[0], v[1] + EYE_HEIGHT, v[2]), v[3], v[4]
        if tr["keyframeType"] == "CAMERA_ORBIT":
            v = evaluate_track(tr, tick)
            if v:
                cx, cy, cz, d, yaw, pitch = v
                yr, pr = math.radians(-yaw), math.radians(pitch)
                look = (math.sin(yr) * math.cos(pr), -math.sin(pr), math.cos(yr) * math.cos(pr))
                return (cx - look[0] * d, cy - look[1] * d, cz - look[2] * d), yaw, pitch
    return None


def track_entity_eye(entity_pos, entity_yaw, entity_pitch, kf: dict, entity_height=1.8, eye_height=1.62):
    """Port of KeyframeChangeTrackEntity.apply for BODY/ROOT/HEAD (given the entity's yaw/pitch for the part).
    Returns (camera_eye_pos, yaw, pitch). Note: for BODY/ROOT the real entity body yaw is not recorded in the
    replay, so previews use the look yaw as an approximation."""
    part = kf["bodyPart"]
    x, y, z = entity_pos
    if part == "HEAD":
        limb = (x, y + eye_height, z)
        yaw, pitch = entity_yaw, entity_pitch
    elif part == "BODY":
        limb = (x, y + entity_height * 0.5, z)
        yaw, pitch = entity_yaw, 0.0
    else:
        limb = (x, y, z)
        yaw, pitch = 0.0, 0.0
    yo, po = kf["yawOffset"], kf["pitchOffset"]
    pitch = pitch * math.cos(math.radians(yo)) + po
    yaw = yaw + yo
    ox, oy, oz = kf.get("viewOffset") or (0, 0, 0)
    # joml rotateX(-pitch) then rotateY(180 - yaw)
    a = math.radians(-pitch)
    oy, oz = oy * math.cos(a) - oz * math.sin(a), oy * math.sin(a) + oz * math.cos(a)
    b = math.radians(180.0 - yaw)
    ox, oz = ox * math.cos(b) + oz * math.sin(b), -ox * math.sin(b) + oz * math.cos(b)
    po_ = kf.get("positionOffset") or (0, 0, 0)
    return (limb[0] + po_[0] + ox, limb[1] + po_[1] + oy, limb[2] + po_[2] + oz), yaw, pitch


# ---------------------------------------------------------------------------
# Shot templates
# ---------------------------------------------------------------------------
class Target:
    """Anything with ``pos(tick)->(x,y,z)`` feet position and ``rot(tick)->(yaw,pitch)``;
    ``flashback_replay.Track`` satisfies this. ``uuid`` is needed only for track_follow."""

    def __init__(self, pos: Callable[[int], tuple], rot: Callable[[int], tuple] | None = None,
                 uuid: str | None = None, name: str = "target"):
        self.pos = pos
        self.rot = rot or (lambda t: (0.0, 0.0))
        self.uuid = uuid
        self.name = name


def as_target(obj, uuid: str | None = None) -> Target:
    if isinstance(obj, Target):
        return obj
    return Target(obj.pos, obj.rot, uuid or getattr(obj, "key", None), getattr(obj, "name", None) or "target")


def _ease(kind: str):
    if kind == "linear":
        return lambda u: u
    if kind == "in":
        return lambda u: u * u
    if kind == "out":
        return lambda u: 1 - (1 - u) ** 2
    return lambda u: u * u * (3 - 2 * u)  # smoothstep ("inout")


def _ticks(start: int, seconds: float, samples_per_s: float, minimum: int = 3):
    total = max(2, int(round(seconds * 20)))
    n = max(minimum - 1, int(math.ceil(seconds * samples_per_s)))
    return [start + int(round(i * total / n)) for i in range(n + 1)], total


def _unique(ticks: list[int]) -> list[int]:
    out = []
    for t in ticks:
        if not out or t > out[-1]:
            out.append(t)
    return out


def _yaw_to(src, dst):
    dx, dz = dst[0] - src[0], dst[2] - src[2]
    return math.degrees(math.atan2(-dx, dz))


def _pitch_to(src, dst):
    dx, dy, dz = dst[0] - src[0], dst[1] - src[1], dst[2] - src[2]
    return -math.degrees(math.atan2(dy, math.hypot(dx, dz)))


def _unwrap(prev: float, ang: float) -> float:
    while ang - prev > 180:
        ang -= 360
    while ang - prev < -180:
        ang += 360
    return ang


def orbit(target, start: int, seconds: float = 6.0, radius: float = 6.0, height: float = 2.0,
          revolutions: float = 1.0, direction: int = 1, start_angle: float | None = None,
          center_offset=(0.0, 1.2, 0.0), ease: str = "inout", samples_per_s: float = 4.0,
          name: str | None = None) -> Shot:
    """Camera circles the (moving) target, always looking at it. One CAMERA_ORBIT track.

    radius = horizontal distance, height = camera height above the look-at point.
    ``start_angle`` = camera look yaw at the start (default: target's facing -> camera behind it).
    direction +1 = clockwise seen from above. Yaw is NOT wrapped (orbit interpolation is plain linear/CatmullRom
    on the number, so 360*n works)."""
    tg = as_target(target)
    ticks, total = _ticks(start, seconds, samples_per_s)
    e = _ease(ease)
    d = math.hypot(radius, height)
    pitch = math.degrees(math.atan2(height, radius))
    y0 = tg.rot(start)[0] if start_angle is None else start_angle
    kfs = {}
    n = len(ticks) - 1
    for i, t in enumerate(ticks):
        u = e(i / n)
        px, py, pz = tg.pos(t)
        c = (px + center_offset[0], py + center_offset[1], pz + center_offset[2])
        kfs[t] = orbit_kf(c, d, y0 + direction * 360.0 * revolutions * u, pitch)
    return Shot(name or f"orbit@{start}", "orbit", start, ticks[-1], [Track("CAMERA_ORBIT", kfs)],
                f"orbit r={radius} h={height} rev={revolutions}", dict(radius=radius, height=height))


def drone_pullup(target, start: int, seconds: float = 5.0, start_dist: float = 3.5, end_dist: float = 45.0,
                 start_pitch: float = 8.0, end_pitch: float = 68.0, yaw_drift: float = 35.0,
                 start_angle: float | None = None, center_offset=(0.0, 1.0, 0.0), ease: str = "inout",
                 samples_per_s: float = 5.0, name: str | None = None) -> Shot:
    """Camera starts low and close behind the target and rises/backs away while tilting down (reveal shot)."""
    tg = as_target(target)
    ticks, total = _ticks(start, seconds, samples_per_s)
    e = _ease(ease)
    y0 = tg.rot(start)[0] if start_angle is None else start_angle
    n = len(ticks) - 1
    kfs = {}
    for i, t in enumerate(ticks):
        u = e(i / n)
        px, py, pz = tg.pos(t)
        c = (px + center_offset[0], py + center_offset[1], pz + center_offset[2])
        dist = start_dist * (end_dist / start_dist) ** u          # exponential => constant perceived speed
        kfs[t] = orbit_kf(c, dist, y0 + yaw_drift * u, _lerp(start_pitch, end_pitch, u))
    return Shot(name or f"drone_pullup@{start}", "drone_pullup", start, ticks[-1], [Track("CAMERA_ORBIT", kfs)],
                "rising reveal", dict(start_dist=start_dist, end_dist=end_dist))


def push_in(target, start: int, seconds: float = 3.0, start_dist: float = 14.0, end_dist: float = 3.2,
            pitch: float = 8.0, angle: float | None = None, angle_offset: float = 155.0,
            fov_from: float | None = None, fov_to: float | None = None, center_offset=(0.0, 1.3, 0.0),
            ease: str = "inout", samples_per_s: float = 4.0, name: str | None = None) -> Shot:
    """Dolly in on the target from a fixed world yaw. ``angle`` absolute camera look-yaw, or
    ``target_yaw + angle_offset`` (155 = front 3/4 view). Optional FOV ramp (dolly-zoom: fov_from>fov_to)."""
    tg = as_target(target)
    ticks, total = _ticks(start, seconds, samples_per_s)
    e = _ease(ease)
    yaw = (tg.rot(start)[0] + angle_offset) if angle is None else angle
    n = len(ticks) - 1
    kfs = {}
    for i, t in enumerate(ticks):
        u = e(i / n)
        px, py, pz = tg.pos(t)
        c = (px + center_offset[0], py + center_offset[1], pz + center_offset[2])
        kfs[t] = orbit_kf(c, _lerp(start_dist, end_dist, u), yaw, pitch)
    tracks = [Track("CAMERA_ORBIT", kfs)]
    if fov_from is not None and fov_to is not None:
        tracks.append(Track("FOV", {ticks[0]: fov_kf(fov_from), ticks[-1]: fov_kf(fov_to)}))
    return Shot(name or f"push_in@{start}", "push_in", start, ticks[-1], tracks, "dolly in",
                dict(start_dist=start_dist, end_dist=end_dist))


def flyby(target, start: int, seconds: float = 4.0, side: float = 8.0, height: float = 3.0, ahead: float = 16.0,
          side_sign: int = 1, look_offset=(0.0, 1.2, 0.0), ease: str = "inout", samples_per_s: float = 5.0,
          name: str | None = None) -> Shot:
    """Camera flies in a straight line past the target (abreast of it at mid-shot), always looking at it.
    One CAMERA track (positions computed by us, yaw/pitch aim at the target each sample)."""
    tg = as_target(target)
    ticks, total = _ticks(start, seconds, samples_per_s)
    mid = (ticks[0] + ticks[-1]) // 2
    # heading from the target's motion around mid-shot (fallback: its facing)
    a, b = tg.pos(max(0, mid - 10)), tg.pos(mid + 10)
    hx, hz = b[0] - a[0], b[2] - a[2]
    if math.hypot(hx, hz) < 0.5:
        yaw = math.radians(tg.rot(mid)[0])
        hx, hz = -math.sin(yaw), math.cos(yaw)
    hl = math.hypot(hx, hz)
    fx, fz = hx / hl, hz / hl                      # forward
    rx, rz = -fz, fx                               # right-hand lateral (x right, z down viewed from above: rotate)
    pm = tg.pos(mid)
    A = (pm[0] + side_sign * side * rx - ahead * fx, pm[1] + height, pm[2] + side_sign * side * rz - ahead * fz)
    B = (pm[0] + side_sign * side * rx + ahead * fx, pm[1] + height, pm[2] + side_sign * side * rz + ahead * fz)
    e = _ease(ease)
    n = len(ticks) - 1
    kfs = {}
    prev_yaw = None
    for i, t in enumerate(ticks):
        u = e(i / n)
        eye = tuple(_lerp(A[k], B[k], u) for k in range(3))
        px, py, pz = tg.pos(t)
        look = (px + look_offset[0], py + look_offset[1], pz + look_offset[2])
        yw = _yaw_to(eye, look)
        if prev_yaw is not None:
            yw = _unwrap(prev_yaw, yw)
        prev_yaw = yw
        kfs[t] = camera_eye_kf(eye, yw, _pitch_to(eye, look))
    return Shot(name or f"flyby@{start}", "flyby", start, ticks[-1], [Track("CAMERA", kfs)],
                "straight fly-by", dict(side=side, height=height, ahead=ahead))


def track_follow(target, start: int, seconds: float = 5.0, distance: float = 4.5, up: float = 0.9,
                 part: str = "BODY", yaw_offset: float = 0.0, pitch_offset: float = 10.0,
                 yaw_offset_end: float | None = None, uuid: str | None = None, name: str | None = None) -> Shot:
    """TRACK_ENTITY chase cam: Flashback itself positions the camera ``distance`` behind the entity every frame
    (so it follows exactly even though we only write 2-3 keyframes). Needs the entity UUID.
    viewOffset z>0 = behind the entity (verified in KeyframeChangeTrackEntity.apply)."""
    tg = as_target(target, uuid)
    if not tg.uuid:
        raise ValueError("track_follow needs the entity uuid")
    total = max(2, int(round(seconds * 20)))
    ticks = _unique([start, start + total // 2, start + total])
    ye = yaw_offset if yaw_offset_end is None else yaw_offset_end
    kfs = {}
    for t in ticks:
        u = (t - start) / total
        kfs[t] = track_entity_kf(tg.uuid, part, _lerp(yaw_offset, ye, u), pitch_offset, (0, 0, 0),
                                 (0, up, distance), 0.0)
    return Shot(name or f"follow@{start}", "track_follow", start, ticks[-1], [Track("TRACK_ENTITY", kfs)],
                f"chase cam d={distance} part={part}", dict(distance=distance, part=part))


def timelapse(target, start: int, end: int, video_seconds: float = 6.0, camera: str = "orbit",
              radius: float = 18.0, height: float = 9.0, revolutions: float = 0.5, name: str | None = None,
              pos=None) -> Shot:
    """Speed-up a long stretch (``end-start`` replay ticks) into ``video_seconds`` of video.

    Track layout: TIMELAPSE keyframes at timeline ticks (start, end) with video ticks (0, video_seconds*20) plus
    a camera track (``orbit`` around the target / ``static`` at ``pos`` looking at the target / ``follow``).
    Camera keyframes are placed in *timeline* ticks, evenly in real time (we convert through the linear
    timelapse mapping) so the orbit finishes exactly when the video does."""
    tg = as_target(target)
    vt = max(2, int(round(video_seconds * 20)))
    span = end - start
    n = max(4, int(math.ceil(video_seconds * 4)))
    to_tl = lambda i: start + int(round(i * span / n))
    kfs = {}
    e = _ease("inout" if camera == "orbit" else "linear")
    y0 = tg.rot(start)[0]
    for i in range(n + 1):
        t = to_tl(i)
        px, py, pz = tg.pos(t)
        c = (px, py + 1.2, pz)
        if camera == "orbit":
            kfs[t] = orbit_kf(c, math.hypot(radius, height), y0 + 360 * revolutions * e(i / n),
                              math.degrees(math.atan2(height, radius)))
        else:
            eye = pos or (px + radius, py + height, pz + radius)
            kfs[t] = camera_eye_kf(eye, _yaw_to(eye, c), _pitch_to(eye, c))
    cam_type = "CAMERA_ORBIT" if camera == "orbit" else "CAMERA"
    tl = {start: timelapse_kf(0), end: timelapse_kf(vt)}
    return Shot(name or f"timelapse@{start}", "timelapse", start, end, [Track("TIMELAPSE", tl), Track(cam_type, kfs)],
                f"{span / 20:.0f}s of game in {video_seconds}s", dict(video_seconds=video_seconds))


TEMPLATES = {"orbit": orbit, "drone_pullup": drone_pullup, "push_in": push_in, "flyby": flyby,
             "track_follow": track_follow, "timelapse": timelapse}


# ---------------------------------------------------------------------------
# Automatic planning: replay -> moments -> shots -> editor state + export job list
# ---------------------------------------------------------------------------
DEFAULT_SHOT_SECONDS = {"orbit": 6.0, "drone_pullup": 5.0, "push_in": 3.5, "flyby": 4.5, "track_follow": 6.0}


def auto_shots(replay, max_shots: int = 8, seconds_scale: float = 1.0, lead_s: float = 1.0) -> list[Shot]:
    """Turn ``replay.suggest_moments()`` into Shot objects around the recording player."""
    from .flashback_replay import Replay  # local import to keep modules decoupled

    assert isinstance(replay, Replay)
    tg = as_target(replay.player_track(), replay.local_uuid)
    shots: list[Shot] = []
    for m in replay.suggest_moments(top=max_shots * 2):
        kind = m["suggested_shot"]
        secs = DEFAULT_SHOT_SECONDS.get(kind, 5.0) * seconds_scale
        start = max(0, int(m["tick"] - lead_s * 20))
        end_cap = replay.total_ticks - 2
        if start + int(secs * 20) > end_cap:
            start = max(0, end_cap - int(secs * 20))
        tag = f"{m['kind']}@{m['tick']}"
        if kind == "orbit":
            s = orbit(tg, start, secs, name=tag)
        elif kind == "drone_pullup":
            s = drone_pullup(tg, start, secs, name=tag)
        elif kind == "push_in":
            s = push_in(tg, start, secs, name=tag)
        elif kind == "flyby":
            s = flyby(tg, start, secs, name=tag)
        elif kind == "track_follow":
            s = track_follow(tg, start, secs, name=tag)
        else:
            continue
        s.note = m["reason"]
        shots.append(s)
        if len(shots) >= max_shots:
            break
    return shots


@dataclass
class ExportOptions:
    """Per-job export settings consumed by the flashback_auto mod (maps 1:1 onto ExportSettings)."""

    width: int = 1920
    height: int = 1080
    fps: float = 60.0
    container: str = "MP4"
    codec: str = "H264"
    encoder: str | None = None        # e.g. "libx264", "h264_amf" (None -> Flashback's first valid encoder)
    bitrate: int = 20_000_000
    ssaa: bool = False
    no_gui: bool = True
    reset_rng: bool = False
    record_audio: bool = False
    transparent: bool = False


def jobs_json(replay_path: str | Path, shots: Sequence[Shot], out_dir: str | Path,
              opts: ExportOptions | None = None, prefix: str = "") -> dict:
    """Job list for the flashback_auto mod: one job per scene/shot, rendered to <out_dir>/<prefix><shot>.mp4."""
    opts = opts or ExportOptions()
    out_dir = Path(out_dir)
    jobs = []
    for i, s in enumerate(shots):
        safe = re.sub(r"[^A-Za-z0-9_.@-]+", "_", f"{prefix}{i:02d}_{s.name}")
        jobs.append({
            "scene": i, "name": safe, "start": s.start, "end": s.end,
            "output": str(out_dir / f"{safe}.{opts.container.lower() if opts.container != 'PNG_SEQUENCE' else 'png'}"),
            "width": opts.width, "height": opts.height, "fps": opts.fps, "container": opts.container,
            "codec": opts.codec, "encoder": opts.encoder, "bitrate": opts.bitrate, "ssaa": opts.ssaa,
            "noGui": opts.no_gui, "resetRng": opts.reset_rng, "recordAudio": opts.record_audio,
            "transparent": opts.transparent, "kind": s.kind, "note": s.note,
        })
    return {"version": 1, "replay": str(replay_path), "jobs": jobs}


# ---------------------------------------------------------------------------
# Self check + CLI
# ---------------------------------------------------------------------------
def selfcheck(verbose: bool = True) -> list[str]:
    """Round-trip + numeric sanity of every template on a synthetic walking target."""
    errs: list[str] = []
    walk = Target(lambda t: (10.0 + 0.2 * t, 64.0, 5.0 + 0.05 * t), lambda t: (-90.0, 5.0),
                  "5bbc695b-1bcf-3837-8441-a51d0fa760a5", "walker")
    shots = [
        orbit(walk, 100, 6.0, radius=6, height=2),
        drone_pullup(walk, 200, 5.0),
        push_in(walk, 300, 3.0, fov_from=70, fov_to=45),
        flyby(walk, 400, 4.0),
        track_follow(walk, 500, 5.0),
        timelapse(walk, 600, 3600, 6.0),
    ]
    st = build_state(shots, Visuals(night_vision=True, time_of_day=18000), "C:/x/replay.zip")
    errs += roundtrip_check(st)
    # orbit: camera must stay at constant horizontal distance + height from the moving centre
    sc = st["scenes"][0]
    for t in range(100, 220, 7):
        pose = camera_pose(sc, t)
        px, py, pz = walk.pos(t)
        (cx, cy, cz), yaw, pitch = pose
        hd = math.hypot(cx - px, cz - pz)
        dh = cy - (py + 1.2)
        if abs(hd - 6.0) > 0.35 or abs(dh - 2.0) > 0.35:
            errs.append(f"orbit @ {t}: horizontal {hd:.2f} (want 6) height {dh:.2f} (want 2)")
    # orbit must look at the centre: look vector * d + cam == centre
    (cx, cy, cz), yaw, pitch = camera_pose(sc, 150)
    px, py, pz = walk.pos(150)
    yr, pr = math.radians(-yaw), math.radians(pitch)
    d = math.dist((cx, cy, cz), (px, py + 1.2, pz))
    la = (cx + math.sin(yr) * math.cos(pr) * d, cy - math.sin(pr) * d, cz + math.cos(yr) * math.cos(pr) * d)
    if math.dist(la, (px, py + 1.2, pz)) > 0.4:
        errs.append("orbit camera does not look at the centre")
    # flyby aims at target
    sc2 = st["scenes"][3]
    (cx, cy, cz), yaw, pitch = camera_pose(sc2, 420)
    px, py, pz = walk.pos(420)
    want_yaw = _yaw_to((cx, cy, cz), (px, py + 1.2, pz))
    if abs(_wrap180(yaw - want_yaw)) > 2.0:
        errs.append(f"flyby yaw {yaw:.1f} != aim {want_yaw:.1f}")
    # track_follow: camera ends up `distance` behind the player along its facing
    kf = st["scenes"][4]["keyframeTracks"][0]["keyframesByTick"]["500"]
    eye, y, p = track_entity_eye(walk.pos(500), -90.0, 5.0, kf)
    behind = math.hypot(eye[0] - walk.pos(500)[0], eye[2] - walk.pos(500)[2])
    if abs(behind - 4.5) > 0.2:
        errs.append(f"track_follow offset {behind:.2f} != 4.5")
    # timelapse speed: (3600-600)/(120-0)*20 = 500 ticks/s
    tl = st["scenes"][5]["keyframeTracks"][0]["keyframesByTick"]
    sp = (3600 - 600) / (tl["3600"]["ticks"] - tl["600"]["ticks"]) * 20
    if abs(sp - 500.0) > 1e-6:
        errs.append(f"timelapse speed {sp}")
    # negative tests: the validator must reject broken input
    bad = copy.deepcopy(st)
    bad["scenes"][0]["keyframeTracks"][0]["keyframesByTick"]["100"]["center"] = [1, 2]
    bad["scenes"][1]["keyframeTracks"][0]["enabled"] = None
    bad["scenes"][2]["keyframeTracks"][0]["keyframesByTick"]["300"]["type"] = "camera"
    if len(validate_state(bad)) < 3:
        errs.append("validator failed to catch deliberately broken state")
    if verbose:
        print("selfcheck:", "OK" if not errs else errs)
    return errs


def _main(argv=None):
    import argparse
    from . import flashback_replay as fr

    ap = argparse.ArgumentParser(description="Plan cinematic shots for a Flashback replay and emit editor state")
    ap.add_argument("replay", nargs="?")
    ap.add_argument("--out", default=None, help="directory for <uuid>.json and jobs.json (default: ./flashback_out)")
    ap.add_argument("--check", action="store_true", help="run the self check only")
    ap.add_argument("--max-shots", type=int, default=6)
    a = ap.parse_args(argv)
    errs = selfcheck()
    if a.check or not a.replay:
        raise SystemExit(1 if errs else 0)
    r = fr.load(a.replay)
    shots = auto_shots(r, max_shots=a.max_shots)
    st = build_state(shots, Visuals(), r.path)
    problems = roundtrip_check(st)
    print(f"replay {r.uuid}: {len(shots)} shots; validation: {problems or 'OK'}")
    for i, s in enumerate(shots):
        print(f"  scene {i}: {s.kind:13s} ticks {s.start}-{s.end} ({s.seconds:.1f}s) {s.name}  [{s.note}]")
    out = Path(a.out or "flashback_out")
    p = write_state(st, r.uuid, out / "editor_states")
    (out / "jobs.json").write_text(json.dumps(jobs_json(r.path, shots, out / "renders"), indent=2), encoding="utf-8")
    print("wrote", p, "and", out / "jobs.json")


if __name__ == "__main__":
    _main()

toolu_01CG5YzXGnf8WMHKtqoGE9cY.content:
"""Generate Flashback (Moulberry) editor-state / keyframes for automatic cinematic B-roll.

Everything here mirrors what the decompiled mod (v0.39.10, MC 1.21.11) reads and writes:

* ``.minecraft/flashback/editor_states/<replay uuid>.json``  <- ``EditorState`` serialised with
  ``FlashbackGson.COMPRESSED`` (Gson). The file name is the ``uuid`` from the replay's metadata.json.
  ``Flashback.openReplayWorld`` calls ``EditorStateManager.get(uuid)`` which loads it, so writing this
  file *before* the replay is opened is how keyframes are injected without touching the GUI.
* Timeline unit = **replay ticks (20/s)**; keyframes live in ``scene.keyframeTracks[i].keyframesByTick``
  keyed by tick-as-string. One scene == one shot (own tracks + own export range).
* Camera conventions (verified from ``KeyframeChangeCameraPosition*`` / ``KeyframeChangeTrackEntity``):
    - ``camera`` keyframe ``position`` is the *feet* position of the camera entity; the eye is +1.62.
    - ``camera_orbit``: camera eye = center - look(yaw,pitch) * distance, facing (yaw,pitch).
      ``center`` is the world point to look at (use eye height of the subject).
    - MC angles: yaw 0 = +Z (south), 90 = -X (west); pitch +90 = straight down.

Public API
----------
Shot templates (all return a :class:`Shot`):  ``orbit``, ``drone_pullup``, ``push_in``, ``flyby``,
``track_follow``, ``timelapse``.   Build a document with :func:`build_state`, validate with
:func:`validate_state`, write with :func:`write_state`, plan automatically with :func:`auto_shots`.

CLI demo:  python -m mcstudio.flashback_keyframes <replay.zip> [--out DIR]
"""
from __future__ import annotations

import copy
import json
import math
import re
import uuid as _uuid
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Iterable, Sequence

EYE_HEIGHT = 1.62  # standing player/spectator camera eye height (Entity.getEyeHeight)

# ---------------------------------------------------------------------------
# Schema constants (from KeyframeType.id(), Keyframe.TypeAdapter, enums)
# ---------------------------------------------------------------------------
TRACK_TYPES = {
    # track id (KeyframeType.id())   -> keyframe "type" string used inside the keyframe object
    "CAMERA": "camera",
    "CAMERA_ORBIT": "camera_orbit",
    "TRACK_ENTITY": "track_entity",
    "CAMERA_SHAKE": "camera_shake",
    "FOV": "fov",
    "SPEED": "tickrate",
    "TIMELAPSE": "timelapse",
    "TIME_OF_DAY": "time",
    "FREEZE": "freeze",
    "BLOCK_OVERRIDE": "block_override",
    "AUDIO": "audio",
}
INTERPOLATIONS = ("SMOOTH", "LINEAR", "EASE_IN", "EASE_OUT", "EASE_IN_OUT", "HOLD", "HERMITE")
BODY_PARTS = ("HEAD", "BODY", "ROOT")
WEATHER = ("NONE", "CLEAR", "OVERCAST", "RAINING", "SNOWING", "THUNDERING")
SIZING = ("KEEP_ASPECT_RATIO", "CHANGE_ASPECT_RATIO", "FILL", "UNDERLAY")
ASPECTS = ("ASPECT_16_9", "ASPECT_9_16", "ASPECT_240_1", "ASPECT_1_1", "ASPECT_4_3", "ASPECT_3_2")
GLOWING = ("DEFAULT", "FORCE_GLOW", "FORCE_NO_GLOW")
VIDEO_CONTAINERS = ("MP4", "MKV", "AVI", "MOV", "PNG_SEQUENCE", "WEBP", "WEBM", "GIF")
VIDEO_CODECS = ("H264", "H265", "AV1", "VP9", "PRO_RES", "QUICK_TIME", "WEBP", "GIF")

_UUID_RE = re.compile(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$")

# ReplayVisuals field -> (python type tag, default). Source: com.moulberry.flashback.visuals.ReplayVisuals
VISUALS_FIELDS: dict[str, tuple[str, object]] = {
    "showChat": ("bool", False), "showBossBar": ("bool", False), "showTitleText": ("bool", False),
    "showScoreboard": ("bool", False), "showActionBar": ("bool", False), "showHotbar": ("bool", True),
    "renderBlocks": ("bool", True), "renderEntities": ("bool", True), "renderPlayers": ("bool", True),
    "renderParticles": ("bool", True), "renderSky": ("bool", True),
    "skyColour": ("f3", [0.0, 1.0, 0.0]),
    "renderNametags": ("bool", True), "renderBeaconBeams": ("bool", True),
    "overrideFog": ("bool", False), "overrideFogStart": ("float", 0.0), "overrideFogEnd": ("float", 256.0),
    "overrideFogColour": ("bool", False), "fogColour": ("f3", [0.0, 1.0, 0.0]),
    "overrideFov": ("bool", False), "overrideFovAmount": ("float", -1.0),
    "overrideCameraShake": ("bool", False), "cameraShakeSplitParams": ("bool", False),
    "cameraShakeYFrequency": ("float", 1.0), "cameraShakeYAmplitude": ("float", 1.0),
    "cameraShakeXFrequency": ("float", 1.0), "cameraShakeXAmplitude": ("float", 1.0),
    "overrideRoll": ("bool", False), "overrideRollAmount": ("float", 0.0),
    "overrideWeatherMode": ("enum:WEATHER", "NONE"),
    "overrideTimeOfDay": ("long", -1),
    "overrideNightVision": ("bool", False),
    "ruleOfThirdsGuide": ("bool", False), "centerGuide": ("bool", False), "cameraPath": ("bool", True),
    "sizing": ("enum:SIZING", "KEEP_ASPECT_RATIO"), "changeAspectRatio": ("enum:ASPECTS", "ASPECT_16_9"),
    "disableServerResourcePack": ("bool", False),
}


def default_visuals() -> dict:
    return {k: copy.deepcopy(v[1]) for k, v in VISUALS_FIELDS.items()}


@dataclass
class Visuals:
    """High level visual overrides applied to the whole editor state (``replayVisuals``)."""

    hide_nametags: bool = True
    hide_hud: bool = True           # chat/boss bar/title/scoreboard/action bar/hotbar off
    night_vision: bool = False
    time_of_day: int | None = None  # 0..24000 (6000 = noon, 18000 = midnight); None = leave replay time
    weather: str = "NONE"
    fov: float | None = None        # global override (degrees); None = keep the in-game FOV
    camera_path_overlay: bool = False  # the editor's camera-path gizmo (never wanted in a render)
    render_particles: bool = True
    aspect: str | None = None       # e.g. "ASPECT_9_16" for shorts -> sizing CHANGE_ASPECT_RATIO
    extra: dict = field(default_factory=dict)  # raw replayVisuals overrides

    def to_dict(self) -> dict:
        d = default_visuals()
        if self.hide_nametags:
            d["renderNametags"] = False
        if self.hide_hud:
            for k in ("showChat", "showBossBar", "showTitleText", "showScoreboard", "showActionBar", "showHotbar"):
                d[k] = False
        d["overrideNightVision"] = bool(self.night_vision)
        if self.time_of_day is not None:
            d["overrideTimeOfDay"] = int(self.time_of_day)
        d["overrideWeatherMode"] = self.weather
        if self.fov is not None:
            d["overrideFov"] = True
            d["overrideFovAmount"] = float(self.fov)
        d["cameraPath"] = bool(self.camera_path_overlay)
        d["renderParticles"] = bool(self.render_particles)
        if self.aspect:
            d["sizing"] = "CHANGE_ASPECT_RATIO"
            d["changeAspectRatio"] = self.aspect
        d.update(self.extra)
        return d


# ---------------------------------------------------------------------------
# Keyframe constructors (dict form == what Keyframe.TypeAdapter serialises)
# ---------------------------------------------------------------------------
def _f(x):
    return float(x)


def vec3(v) -> list[float]:
    x, y, z = v
    return [_f(x), _f(y), _f(z)]


def camera_kf(feet_pos, yaw: float, pitch: float, roll: float = 0.0, interp: str = "SMOOTH") -> dict:
    return {"position": vec3(feet_pos), "yaw": _f(yaw), "pitch": _f(pitch), "roll": _f(roll),
            "type": "camera", "interpolation_type": interp}


def camera_eye_kf(eye_pos, yaw, pitch, roll=0.0, interp="SMOOTH") -> dict:
    """Camera keyframe from a desired *eye* position (converts to feet position)."""
    x, y, z = eye_pos
    return camera_kf((x, y - EYE_HEIGHT, z), yaw, pitch, roll, interp)


def orbit_kf(center, distance: float, yaw: float, pitch: float, interp: str = "SMOOTH") -> dict:
    return {"center": vec3(center), "distance": _f(distance), "yaw": _f(yaw), "pitch": _f(pitch),
            "type": "camera_orbit", "interpolation_type": interp}


def track_entity_kf(target_uuid: str, part: str = "BODY", yaw_offset: float = 0.0, pitch_offset: float = 0.0,
                    position_offset=(0, 0, 0), view_offset=(0, 0, 0), roll: float = 0.0,
                    interp: str = "SMOOTH") -> dict:
    return {"target": target_uuid, "bodyPart": part, "yawOffset": _f(yaw_offset), "pitchOffset": _f(pitch_offset),
            "positionOffset": vec3(position_offset), "viewOffset": vec3(view_offset),
            "type": "track_entity", "roll": _f(roll), "interpolation_type": interp}


def fov_kf(fov: float, interp: str = "SMOOTH") -> dict:
    return {"fov": _f(fov), "type": "fov", "interpolation_type": interp}


def tickrate_kf(tickrate: float, interp: str = "SMOOTH") -> dict:
    """Speed track. ``tickrate`` is replay ticks per real second: 20 = 1x, 40 = 2x, 10 = 0.5x."""
    return {"tickrate": _f(tickrate), "type": "tickrate", "interpolation_type": interp}


def freeze_kf(frozen: bool, delay: int = 0, interp: str = "HOLD") -> dict:
    return {"freeze": bool(frozen), "freezeDelay": int(delay), "type": "freeze", "interpolation_type": interp}


def timelapse_kf(video_ticks: int) -> dict:
    """Timelapse keyframe. Placed at timeline tick K it says 'output video time == video_ticks (20/s)'.
    Speed between two keyframes = (K2-K1)/(T2-T1)*20 replay ticks/s (KeyframeTrack.tryApplyKeyframesTimelapse).
    No interpolation_type is serialised (always LINEAR)."""
    return {"ticks": int(video_ticks), "type": "timelapse"}


def time_of_day_kf(time: int, interp: str = "SMOOTH") -> dict:
    return {"time": int(time), "type": "time", "interpolation_type": interp}


def shake_kf(freq_x=1.0, amp_x=1.0, freq_y=1.0, amp_y=1.0, split=False, interp="SMOOTH") -> dict:
    d = {"frequencyX": _f(freq_x), "amplitudeX": _f(amp_x), "frequencyY": _f(freq_y), "amplitudeY": _f(amp_y)}
    if split:
        d["splitParams"] = True
    d.update({"type": "camera_shake", "interpolation_type": interp})
    return d


# ---------------------------------------------------------------------------
# Document model
# ---------------------------------------------------------------------------
@dataclass
class Track:
    type: str                                   # key of TRACK_TYPES
    keyframes: dict[int, dict] = field(default_factory=dict)
    enabled: bool = True
    custom_name: str | None = None
    custom_colour: int = 0

    def to_dict(self) -> dict:
        d = {"keyframeType": self.type,
             "keyframesByTick": {str(k): v for k, v in sorted(self.keyframes.items())},
             "enabled": self.enabled}
        if self.custom_name:
            d["customName"] = self.custom_name
        d["customColour"] = self.custom_colour
        return d


@dataclass
class Shot:
    """One shot == one editor scene. ``start``/``end`` are replay ticks (export range)."""

    name: str
    kind: str
    start: int
    end: int
    tracks: list[Track]
    note: str = ""
    params: dict = field(default_factory=dict)

    @property
    def seconds(self) -> float:
        return (self.end - self.start) / 20.0

    def to_scene(self) -> dict:
        return {
            "name": self.name,
            "keyframeTracks": [t.to_dict() for t in self.tracks],
            "exportStartTicks": int(self.start),
            "exportEndTicks": int(self.end),
            "history": {"entries": [], "position": 0},
        }


def empty_state(replay_path: str | None = None, visuals: Visuals | None = None) -> dict:
    """A blank EditorState dict, identical in shape to what Flashback itself writes."""
    return {
        "replayVisuals": (visuals or Visuals()).to_dict(),
        "sceneLock": {},
        "scenes": [],
        "sceneIndex": 0,
        "zoomMin": 0.0,
        "zoomMax": 1.0,
        "usedByPaths": [str(replay_path)] if replay_path else [],
        "hideDuringExport": [],
        "hideAllSpectators": False,
        "muteVoice": [],
        "hideNametags": [],
        "skinOverride": {},
        "skinOverrideFromFile": {},
        "nameOverride": {},
        "glowingOverride": {},
        "hideTeamPrefix": [],
        "hideTeamSuffix": [],
        "hideBelowName": [],
        "hideCape": [],
        "filteredEntities": [],
        "filteredParticles": [],
        "hiddenEquipment": {},
        "hiddenModelParts": {},
    }


def build_state(shots: Sequence[Shot], visuals: Visuals | None = None, replay_path: str | Path | None = None,
                hide_entities: Iterable[str] = (), scene_index: int = 0) -> dict:
    """EditorState dict with one scene per shot."""
    st = empty_state(str(replay_path) if replay_path else None, visuals)
    st["scenes"] = [s.to_scene() for s in shots]
    if not st["scenes"]:  # Flashback always wants >= 1 scene
        st["scenes"] = [{"name": "Scene 1", "keyframeTracks": [], "exportStartTicks": -1, "exportEndTicks": -1,
                         "history": {"entries": [], "position": 0}}]
    st["sceneIndex"] = scene_index
    st["hideDuringExport"] = [str(u) for u in hide_entities]
    return st


def dumps_state(state: dict) -> str:
    """Compact JSON like ``FlashbackGson.COMPRESSED`` (no spaces, doubles keep '.0')."""
    return json.dumps(state, separators=(",", ":"), ensure_ascii=False)


def write_state(state: dict, replay_uuid: str, folder: str | Path) -> Path:
    """Write ``<folder>/<replay_uuid>.json``. ``folder`` must be ``<.minecraft>/flashback/editor_states``
    for Flashback to pick it up -- this function does not default to it on purpose.
    The previous file (if any) is kept as ``.json.old`` exactly like EditorStateManager.save() does."""
    errs = validate_state(state)
    if errs:
        raise ValueError("invalid editor state:\n  " + "\n  ".join(errs))
    folder = Path(folder)
    folder.mkdir(parents=True, exist_ok=True)
    p = folder / f"{replay_uuid}.json"
    if p.exists():
        p.replace(folder / f"{replay_uuid}.json.old")
    p.write_text(dumps_state(state), encoding="utf-8")
    return p


# ---------------------------------------------------------------------------
# Validation == the rules the Gson TypeAdapters/constructors enforce on load
# ---------------------------------------------------------------------------
def _is_num(x):
    return isinstance(x, (int, float)) and not isinstance(x, bool)


def _vec3_ok(v):
    return isinstance(v, list) and len(v) == 3 and all(_is_num(c) for c in v)


def validate_keyframe(track_type: str, kf: dict, where: str) -> list[str]:
    errs: list[str] = []
    want = TRACK_TYPES.get(track_type)
    if want is None:
        return [f"{where}: unknown track type {track_type!r}"]
    if not isinstance(kf, dict) or kf.get("type") != want:
        return [f"{where}: keyframe type {kf.get('type') if isinstance(kf, dict) else kf!r} != {want!r} "
                f"(Keyframe.TypeAdapter + ClassCastException when a track mixes types)"]
    it = kf.get("interpolation_type")
    if it is not None and it not in INTERPOLATIONS:
        errs.append(f"{where}: bad interpolation_type {it!r}")
    if track_type in ("TIMELAPSE", "BLOCK_OVERRIDE", "AUDIO"):
        pass
    req: dict[str, str] = {
        "CAMERA": "position",                       # yaw/pitch/roll default to 0
        "CAMERA_ORBIT": "center,distance,yaw,pitch",
        "TRACK_ENTITY": "target,bodyPart,yawOffset,pitchOffset",
        "CAMERA_SHAKE": "frequencyX,amplitudeX,frequencyY,amplitudeY",
        "FOV": "fov",
        "SPEED": "tickrate",
        "TIMELAPSE": "ticks",
        "TIME_OF_DAY": "time",
        "FREEZE": "freeze",
    }.get(track_type, "")
    for k in filter(None, req.split(",")):
        if k not in kf:
            errs.append(f"{where}: missing required field {k!r} (getAs*() on null -> NPE on load)")
    for k in ("position", "center", "positionOffset", "viewOffset"):
        if k in kf and kf[k] is not None and not _vec3_ok(kf[k]):
            errs.append(f"{where}: {k} must be a 3-number array (Vector3dTypeAdapater), got {kf[k]!r}")
    for k in ("yaw", "pitch", "roll", "distance", "yawOffset", "pitchOffset", "fov", "tickrate",
              "frequencyX", "amplitudeX", "frequencyY", "amplitudeY"):
        if k in kf and not _is_num(kf[k]):
            errs.append(f"{where}: {k} must be a number")
    for k in ("ticks", "time", "freezeDelay"):
        if k in kf and (not isinstance(kf[k], int) or isinstance(kf[k], bool)):
            errs.append(f"{where}: {k} must be an int (getAsInt)")
    if "freeze" in kf and not isinstance(kf["freeze"], bool):
        errs.append(f"{where}: freeze must be bool")
    if track_type == "TRACK_ENTITY":
        if not (isinstance(kf.get("target"), str) and _UUID_RE.match(kf["target"])):
            errs.append(f"{where}: target must be a UUID string")
        if kf.get("bodyPart") not in BODY_PARTS:
            errs.append(f"{where}: bodyPart must be one of {BODY_PARTS}")
    if track_type == "FOV" and _is_num(kf.get("fov")) and not (1.0 <= kf["fov"] <= 110.0):
        errs.append(f"{where}: fov {kf['fov']} outside editor slider range 1..110 (not enforced by loader)")
    if track_type == "SPEED" and _is_num(kf.get("tickrate")) and kf["tickrate"] <= 0:
        errs.append(f"{where}: tickrate must be > 0 (clamped to 0.001 at runtime)")
    return errs


def validate_state(state: dict) -> list[str]:
    """Return a list of problems (empty == the loader would accept it). Mirrors EditorState/EditorScene/
    KeyframeTrack/Keyframe deserialisation. Note: EditorScene & KeyframeTrack have no no-arg constructor, so Gson
    allocates them with Unsafe and *skips field initialisers* -> every field must be present in the JSON."""
    errs: list[str] = []
    if not isinstance(state, dict):
        return ["state is not an object"]
    rv = state.get("replayVisuals")
    if not isinstance(rv, dict):
        errs.append("replayVisuals missing")
    else:
        for k, (tag, _d) in VISUALS_FIELDS.items():
            if k not in rv:
                continue  # EditorState has a no-arg ctor -> ReplayVisuals initialiser keeps default
            v = rv[k]
            ok = {
                "bool": isinstance(v, bool),
                "float": _is_num(v),
                "long": isinstance(v, int) and not isinstance(v, bool),
                "f3": isinstance(v, list) and len(v) == 3 and all(_is_num(c) for c in v),
            }.get(tag)
            if ok is None and tag.startswith("enum:"):
                ok = v in {"WEATHER": WEATHER, "SIZING": SIZING, "ASPECTS": ASPECTS}[tag.split(":")[1]]
            if not ok:
                errs.append(f"replayVisuals.{k}: bad value {v!r} ({tag})")
        for k in rv:
            if k not in VISUALS_FIELDS:
                errs.append(f"replayVisuals.{k}: unknown field (Gson ignores it)")
    scenes = state.get("scenes")
    if not isinstance(scenes, list) or not scenes:
        errs.append("scenes must be a non-empty list (EditorState.currentScene() = scenes.get(sceneIndex))")
        scenes = []
    si = state.get("sceneIndex", 0)
    if not isinstance(si, int) or not (0 <= si < max(1, len(scenes))):
        errs.append(f"sceneIndex {si!r} out of range")
    for i, sc in enumerate(scenes):
        w = f"scenes[{i}]"
        if not isinstance(sc.get("name"), str):
            errs.append(f"{w}.name missing")
        for k in ("exportStartTicks", "exportEndTicks"):
            if not isinstance(sc.get(k), int):
                errs.append(f"{w}.{k} must be int (-1 = unset)")
        h = sc.get("history")
        if not (isinstance(h, dict) and isinstance(h.get("entries"), list) and isinstance(h.get("position"), int)):
            errs.append(f"{w}.history must be {{entries:[], position:int}} (null after Unsafe alloc otherwise)")
        tracks = sc.get("keyframeTracks")
        if not isinstance(tracks, list):
            errs.append(f"{w}.keyframeTracks must be a list")
            continue
        cam_like = {"CAMERA", "CAMERA_ORBIT", "TRACK_ENTITY"}
        for j, tr in enumerate(tracks):
            tw = f"{w}.keyframeTracks[{j}]"
            tt = tr.get("keyframeType")
            if tt not in TRACK_TYPES:
                errs.append(f"{tw}.keyframeType {tt!r} unknown (KeyframeRegistry.TypeAdapter requireNonNull)")
                continue
            if not isinstance(tr.get("enabled"), bool):
                errs.append(f"{tw}.enabled must be present (Unsafe alloc defaults it to false -> track silently off)")
            if not isinstance(tr.get("customColour", 0), int):
                errs.append(f"{tw}.customColour must be int")
            kfs = tr.get("keyframesByTick")
            if not isinstance(kfs, dict):
                errs.append(f"{tw}.keyframesByTick must be an object (null -> NPE)")
                continue
            for tk, kf in kfs.items():
                if not re.fullmatch(r"-?\d+", str(tk)):
                    errs.append(f"{tw}: tick key {tk!r} not an int")
                elif int(tk) < 0:
                    errs.append(f"{tw}: negative tick {tk}")
                errs += validate_keyframe(tt, kf, f"{tw}@{tk}")
            if tt == "TIMELAPSE":
                ks = sorted(int(k) for k in kfs)
                for a, b in zip(ks, ks[1:]):
                    if kfs[str(b)]["ticks"] <= kfs[str(a)]["ticks"]:
                        errs.append(f"{tw}: timelapse ticks must strictly increase ({a}->{b})")
        tt_cam = [t for t in tracks if t.get("keyframeType") in cam_like and t.get("enabled") and t.get("keyframesByTick")]
        if len(tt_cam) > 1:
            errs.append(f"{w}: {len(tt_cam)} enabled camera-type tracks; later tracks override earlier ones "
                        f"(EditorState.applyKeyframes applies each change class once, last applyCameraPosition wins)")
    for k in ("usedByPaths", "hideDuringExport", "muteVoice", "hideNametags", "hideTeamPrefix", "hideTeamSuffix",
              "hideBelowName", "hideCape", "filteredEntities", "filteredParticles"):
        if k in state and not isinstance(state[k], list):
            errs.append(f"{k} must be a list")
    for k in ("hideDuringExport", "muteVoice", "hideNametags", "hideTeamPrefix", "hideTeamSuffix", "hideBelowName",
              "hideCape"):
        for u in state.get(k, []):
            if not (isinstance(u, str) and _UUID_RE.match(u)):
                errs.append(f"{k}: {u!r} not a UUID")
    for k in ("skinOverride", "skinOverrideFromFile", "nameOverride", "glowingOverride", "hiddenEquipment",
              "hiddenModelParts"):
        if k in state and not isinstance(state[k], dict):
            errs.append(f"{k} must be an object")
    for u, g in state.get("glowingOverride", {}).items():
        if g not in GLOWING:
            errs.append(f"glowingOverride[{u}] bad enum {g!r}")
    return errs


def roundtrip_check(state: dict) -> list[str]:
    """Serialise -> parse -> serialise again; must be byte-identical (what Gson does on load+autosave)."""
    errs = validate_state(state)
    s1 = dumps_state(state)
    s2 = dumps_state(json.loads(s1))
    if s1 != s2:
        errs.append("JSON round trip is not stable")
    return errs


# ---------------------------------------------------------------------------
# Port of the runtime evaluation (KeyframeTrack.createKeyframeChange) for previews/self-checks.
# Supports CAMERA / CAMERA_ORBIT / FOV with SMOOTH / LINEAR / HOLD / EASE_*  (no speed tracks).
# ---------------------------------------------------------------------------
def _wrap180(a):  # Mth.wrapDegrees
    a = a % 360.0
    if a >= 180.0:
        a -= 360.0
    if a < -180.0:
        a += 360.0
    return a


def _lerp(a, b, t):
    return a + (b - a) * t


def _cr_core(p, tj, t, time1, time2, time3, lerp=_lerp):
    averageTj = (tj[0] + tj[1] + tj[2]) / 3.0
    if averageTj == 0.0:
        return None
    relation = (time3 / 3.0) / averageTj

    def dt(tjk, span, ok):
        if not ok:
            return 0.0
        f = tjk * relation / span
        f = max(0.4, min(2.5, f))
        return tjk * relation / f

    d1 = dt(tj[0], time1, time1 > 0)
    d2 = dt(tj[1], time2 - time1, time2 - time1 > 0)
    d3 = dt(tj[2], time3 - time2, time3 - time2 > 0)
    t0 = 0.0
    t1 = t0 + d1
    t2 = t1 + d2
    t3 = t2 + d3
    tt = t1 + (t2 - t1) * t
    a1 = lerp(p[0], p[1], 0.5 if t0 == t1 else (tt - t0) / (t1 - t0))
    a2 = lerp(p[1], p[2], 0.5 if t1 == t2 else (tt - t1) / (t2 - t1))
    a3 = lerp(p[2], p[3], 0.5 if t2 == t3 else (tt - t2) / (t3 - t2))
    b1 = lerp(a1, a2, 0.5 if t0 == t2 else (tt - t0) / (t2 - t0))
    b2 = lerp(a2, a3, 0.5 if t1 == t3 else (tt - t1) / (t3 - t1))
    return lerp(b1, b2, 0.5 if t1 == t2 else (tt - t1) / (t2 - t1))


def _cr_value(p0, p1, p2, p3, time1, time2, time3, amount):
    tj = [math.sqrt(abs(p0 - p1)), math.sqrt(abs(p1 - p2)), math.sqrt(abs(p2 - p3))]
    r = _cr_core([p0, p1, p2, p3], tj, amount, time1, time2, time3)
    return p1 if r is None else r


def _cr_degrees(p0, p1, p2, p3, time1, time2, time3, amount):
    d1, d2, d3 = _wrap180(p1 - p0), _wrap180(p2 - p1), _wrap180(p3 - p2)
    p0 = _wrap180(p0)
    p1 = p0 + d1
    p2 = p1 + d2
    p3 = p2 + d3
    tj = [math.sqrt(abs(_wrap180(p0 - p1))), math.sqrt(abs(_wrap180(p1 - p2))), math.sqrt(abs(_wrap180(p2 - p3)))]
    r = _cr_core([p0, p1, p2, p3], tj, amount, time1, time2, time3)
    return p1 if r is None else r


def _cr_position(P0, P1, P2, P3, time1, time2, time3, amount):
    def tjf(a, b):
        return ((b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2 + (b[2] - a[2]) ** 2) ** 0.25

    tj = [tjf(P0, P1), tjf(P1, P2), tjf(P2, P3)]
    if sum(tj) / 3.0 == 0.0:
        return list(P1)
    # same weights for all 3 axes => compute the knot times once, then blend per axis
    out = []
    for ax in range(3):
        r = _cr_core([P0[ax], P1[ax], P2[ax], P3[ax]], tj, amount, time1, time2, time3)
        out.append(P1[ax] if r is None else r)
    return out


def _sided(interp: str):
    return {"SMOOTH": ("SMOOTH", "SMOOTH"), "LINEAR": ("LINEAR", "LINEAR"), "EASE_IN": ("EASE", "LINEAR"),
            "EASE_OUT": ("LINEAR", "EASE"), "EASE_IN_OUT": ("EASE", "EASE"), "HOLD": ("HOLD", "HOLD"),
            "HERMITE": ("HERMITE", "HERMITE")}[interp]


def _sided_interp(left, right, amount):  # SidedInterpolationType.interpolate
    special = ("SMOOTH", "HERMITE")
    if left in special:
        if right in special:
            left = right = "LINEAR"
        else:
            left = right
    elif right in special:
        right = left
    if left == "HOLD":
        return 0.0
    if right == "HOLD":
        right = left
    if left == "LINEAR":
        if right == "LINEAR":
            return amount
        if right == "EASE":
            return 1.0 - (1.0 - amount) ** 3
    elif left == "EASE":
        if right == "LINEAR":
            return amount ** 3
        if right == "EASE":
            return 4 * amount ** 3 if amount < 0.5 else 1.0 - (-2.0 * amount + 2.0) ** 3 / 2.0
    raise ValueError("cannot interpolate")


def _fields(tt, kf):
    if tt == "CAMERA":
        return list(kf["position"]) + [kf.get("yaw", 0.0), kf.get("pitch", 0.0), kf.get("roll", 0.0)]
    if tt == "CAMERA_ORBIT":
        return list(kf["center"]) + [kf["distance"], kf["yaw"], kf["pitch"]]
    if tt == "FOV":
        return [1.0 / math.tan(math.radians(kf["fov"]) * 0.5)]
    raise NotImplementedError(tt)


def _lin_change(tt, a, b, t):
    out = [_lerp(x, y, t) for x, y in zip(a, b)]
    if tt == "CAMERA":  # linearAngle for yaw/pitch/roll
        for i in (3, 4, 5):
            d = _wrap180(b[i] - a[i])
            out[i] = a[i] + max(-180.0, min(180.0, d * t))
    return out


def _smooth_change(tt, k0, k1, k2, k3, t0, t1, t2, t3, amount):
    time1, time2, time3 = t1 - t0, t2 - t0, t3 - t0
    f = [_fields(tt, k) for k in (k0, k1, k2, k3)]
    if tt in ("CAMERA", "CAMERA_ORBIT"):
        pos = _cr_position(f[0][:3], f[1][:3], f[2][:3], f[3][:3], time1, time2, time3, amount)
        rest = []
        for i in range(3, len(f[0])):
            fn = _cr_degrees if (tt == "CAMERA") else _cr_value
            rest.append(fn(f[0][i], f[1][i], f[2][i], f[3][i], time1, time2, time3, amount))
        return pos + rest
    return [_cr_value(f[0][0], f[1][0], f[2][0], f[3][0], time1, time2, time3, amount)]


def evaluate_track(track: dict, tick: float):
    """Value of a serialised track at ``tick`` (floats list) or None. Raises on unsupported types/interps."""
    tt = track["keyframeType"]
    kfs = {int(k): v for k, v in track["keyframesByTick"].items()}
    if not kfs or not track.get("enabled", True):
        return None
    keys = sorted(kfs)
    lower = max((k for k in keys if k <= int(tick)), default=None)
    if lower is None:
        return None
    lk = kfs[lower]
    if tick == lower:
        return _fields(tt, lk)
    li = lk.get("interpolation_type") or "SMOOTH"
    left = _sided(li)[1]
    if left == "HOLD":
        return _fields(tt, lk)
    ceil = min((k for k in keys if k >= lower + 1), default=None)
    if ceil is None:
        return _fields(tt, lk) if int(tick) == lower else None
    ck = kfs[ceil]
    right = _sided(ck.get("interpolation_type") or "SMOOTH")[0]
    if right == "HOLD":
        right = left
    amount = (tick - lower) / (ceil - lower)
    if "HERMITE" in (left, right):
        raise NotImplementedError("HERMITE evaluation not ported")
    lc = rc = None
    if "SMOOTH" in (left, right):
        before = max((k for k in keys if k <= lower - 1), default=None)
        if before is None or (kfs[before].get("interpolation_type") == "HOLD"):
            before = lower
        after = min((k for k in keys if k >= ceil + 1), default=None)
        if after is None or ck.get("interpolation_type") == "HOLD":
            after = ceil
        sc = _smooth_change(tt, kfs[before], lk, ck, kfs[after], before, lower, ceil, after, amount)
        if left == "SMOOTH":
            lc = sc
        if right == "SMOOTH":
            rc = sc
    if lc is None or rc is None:
        adj = _sided_interp(left, right, amount)
        base = _fields(tt, lk)
        if adj != 0.0:
            base = _lin_change(tt, base, _fields(tt, ck), adj)
        lc = lc if lc is not None else base
        rc = rc if rc is not None else base
    return _lin_change(tt, lc, rc, amount)


def camera_pose(scene: dict, tick: float):
    """Camera eye position + yaw/pitch at ``tick`` for the scene's camera-type track (CAMERA or CAMERA_ORBIT)."""
    for tr in scene["keyframeTracks"]:
        if tr["keyframeType"] == "CAMERA":
            v = evaluate_track(tr, tick)
            if v:
                return (v[0], v[1] + EYE_HEIGHT, v[2]), v[3], v[4]
        if tr["keyframeType"] == "CAMERA_ORBIT":
            v = evaluate_track(tr, tick)
            if v:
                cx, cy, cz, d, yaw, pitch = v
                yr, pr = math.radians(-yaw), math.radians(pitch)
                look = (math.sin(yr) * math.cos(pr), -math.sin(pr), math.cos(yr) * math.cos(pr))
                return (cx - look[0] * d, cy - look[1] * d, cz - look[2] * d), yaw, pitch
    return None


def track_entity_eye(entity_pos, entity_yaw, entity_pitch, kf: dict, entity_height=1.8, eye_height=1.62):
    """Port of KeyframeChangeTrackEntity.apply for BODY/ROOT/HEAD (given the entity's yaw/pitch for the part).
    Returns (camera_eye_pos, yaw, pitch). Note: for BODY/ROOT the real entity body yaw is not recorded in the
    replay, so previews use the look yaw as an approximation."""
    part = kf["bodyPart"]
    x, y, z = entity_pos
    if part == "HEAD":
        limb = (x, y + eye_height, z)
        yaw, pitch = entity_yaw, entity_pitch
    elif part == "BODY":
        limb = (x, y + entity_height * 0.5, z)
        yaw, pitch = entity_yaw, 0.0
    else:
        limb = (x, y, z)
        yaw, pitch = 0.0, 0.0
    yo, po = kf["yawOffset"], kf["pitchOffset"]
    pitch = pitch * math.cos(math.radians(yo)) + po
    yaw = yaw + yo
    ox, oy, oz = kf.get("viewOffset") or (0, 0, 0)
    # joml rotateX(-pitch) then rotateY(180 - yaw)
    a = math.radians(-pitch)
    oy, oz = oy * math.cos(a) - oz * math.sin(a), oy * math.sin(a) + oz * math.cos(a)
    b = math.radians(180.0 - yaw)
    ox, oz = ox * math.cos(b) + oz * math.sin(b), -ox * math.sin(b) + oz * math.cos(b)
    po_ = kf.get("positionOffset") or (0, 0, 0)
    return (limb[0] + po_[0] + ox, limb[1] + po_[1] + oy, limb[2] + po_[2] + oz), yaw, pitch


# ---------------------------------------------------------------------------
# Shot templates
# ---------------------------------------------------------------------------
class Target:
    """Anything with ``pos(tick)->(x,y,z)`` feet position and ``rot(tick)->(yaw,pitch)``;
    ``flashback_replay.Track`` satisfies this. ``uuid`` is needed only for track_follow."""

    def __init__(self, pos: Callable[[int], tuple], rot: Callable[[int], tuple] | None = None,
                 uuid: str | None = None, name: str = "target"):
        self.pos = pos
        self.rot = rot or (lambda t: (0.0, 0.0))
        self.uuid = uuid
        self.name = name


def as_target(obj, uuid: str | None = None) -> Target:
    if isinstance(obj, Target):
        return obj
    return Target(obj.pos, obj.rot, uuid or getattr(obj, "key", None), getattr(obj, "name", None) or "target")


def _ease(kind: str):
    if kind == "linear":
        return lambda u: u
    if kind == "in":
        return lambda u: u * u
    if kind == "out":
        return lambda u: 1 - (1 - u) ** 2
    return lambda u: u * u * (3 - 2 * u)  # smoothstep ("inout")


def _ticks(start: int, seconds: float, samples_per_s: float, minimum: int = 3):
    total = max(2, int(round(seconds * 20)))
    n = max(minimum - 1, int(math.ceil(seconds * samples_per_s)))
    return [start + int(round(i * total / n)) for i in range(n + 1)], total


def _unique(ticks: list[int]) -> list[int]:
    out = []
    for t in ticks:
        if not out or t > out[-1]:
            out.append(t)
    return out


def _yaw_to(src, dst):
    dx, dz = dst[0] - src[0], dst[2] - src[2]
    return math.degrees(math.atan2(-dx, dz))


def _pitch_to(src, dst):
    dx, dy, dz = dst[0] - src[0], dst[1] - src[1], dst[2] - src[2]
    return -math.degrees(math.atan2(dy, math.hypot(dx, dz)))


def _unwrap(prev: float, ang: float) -> float:
    while ang - prev > 180:
        ang -= 360
    while ang - prev < -180:
        ang += 360
    return ang


def orbit(target, start: int, seconds: float = 6.0, radius: float = 6.0, height: float = 2.0,
          revolutions: float = 1.0, direction: int = 1, start_angle: float | None = None,
          center_offset=(0.0, 1.2, 0.0), ease: str = "inout", samples_per_s: float = 4.0,
          name: str | None = None) -> Shot:
    """Camera circles the (moving) target, always looking at it. One CAMERA_ORBIT track.

    radius = horizontal distance, height = camera height above the look-at point.
    ``start_angle`` = camera look yaw at the start (default: target's facing -> camera behind it).
    direction +1 = clockwise seen from above. Yaw is NOT wrapped (orbit interpolation is plain linear/CatmullRom
    on the number, so 360*n works)."""
    tg = as_target(target)
    ticks, total = _ticks(start, seconds, samples_per_s)
    e = _ease(ease)
    d = math.hypot(radius, height)
    pitch = math.degrees(math.atan2(height, radius))
    y0 = tg.rot(start)[0] if start_angle is None else start_angle
    kfs = {}
    n = len(ticks) - 1
    for i, t in enumerate(ticks):
        u = e(i / n)
        px, py, pz = tg.pos(t)
        c = (px + center_offset[0], py + center_offset[1], pz + center_offset[2])
        kfs[t] = orbit_kf(c, d, y0 + direction * 360.0 * revolutions * u, pitch)
    return Shot(name or f"orbit@{start}", "orbit", start, ticks[-1], [Track("CAMERA_ORBIT", kfs)],
                f"orbit r={radius} h={height} rev={revolutions}", dict(radius=radius, height=height))


def drone_pullup(target, start: int, seconds: float = 5.0, start_dist: float = 3.5, end_dist: float = 45.0,
                 start_pitch: float = 8.0, end_pitch: float = 68.0, yaw_drift: float = 35.0,
                 start_angle: float | None = None, center_offset=(0.0, 1.0, 0.0), ease: str = "inout",
                 samples_per_s: float = 5.0, name: str | None = None) -> Shot:
    """Camera starts low and close behind the target and rises/backs away while tilting down (reveal shot)."""
    tg = as_target(target)
    ticks, total = _ticks(start, seconds, samples_per_s)
    e = _ease(ease)
    y0 = tg.rot(start)[0] if start_angle is None else start_angle
    n = len(ticks) - 1
    kfs = {}
    for i, t in enumerate(ticks):
        u = e(i / n)
        px, py, pz = tg.pos(t)
        c = (px + center_offset[0], py + center_offset[1], pz + center_offset[2])
        dist = start_dist * (end_dist / start_dist) ** u          # exponential => constant perceived speed
        kfs[t] = orbit_kf(c, dist, y0 + yaw_drift * u, _lerp(start_pitch, end_pitch, u))
    return Shot(name or f"drone_pullup@{start}", "drone_pullup", start, ticks[-1], [Track("CAMERA_ORBIT", kfs)],
                "rising reveal", dict(start_dist=start_dist, end_dist=end_dist))


def push_in(target, start: int, seconds: float = 3.0, start_dist: float = 14.0, end_dist: float = 3.2,
            pitch: float = 8.0, angle: float | None = None, angle_offset: float = 155.0,
            fov_from: float | None = None, fov_to: float | None = None, center_offset=(0.0, 1.3, 0.0),
            ease: str = "inout", samples_per_s: float = 4.0, name: str | None = None) -> Shot:
    """Dolly in on the target from a fixed world yaw. ``angle`` absolute camera look-yaw, or
    ``target_yaw + angle_offset`` (155 = front 3/4 view). Optional FOV ramp (dolly-zoom: fov_from>fov_to)."""
    tg = as_target(target)
    ticks, total = _ticks(start, seconds, samples_per_s)
    e = _ease(ease)
    yaw = (tg.rot(start)[0] + angle_offset) if angle is None else angle
    n = len(ticks) - 1
    kfs = {}
    for i, t in enumerate(ticks):
        u = e(i / n)
        px, py, pz = tg.pos(t)
        c = (px + center_offset[0], py + center_offset[1], pz + center_offset[2])
        kfs[t] = orbit_kf(c, _lerp(start_dist, end_dist, u), yaw, pitch)
    tracks = [Track("CAMERA_ORBIT", kfs)]
    if fov_from is not None and fov_to is not None:
        tracks.append(Track("FOV", {ticks[0]: fov_kf(fov_from), ticks[-1]: fov_kf(fov_to)}))
    return Shot(name or f"push_in@{start}", "push_in", start, ticks[-1], tracks, "dolly in",
                dict(start_dist=start_dist, end_dist=end_dist))


def flyby(target, start: int, seconds: float = 4.0, side: float = 8.0, height: float = 3.0, ahead: float = 16.0,
          side_sign: int = 1, look_offset=(0.0, 1.2, 0.0), ease: str = "inout", samples_per_s: float = 5.0,
          name: str | None = None) -> Shot:
    """Camera flies in a straight line past the target (abreast of it at mid-shot), always looking at it.
    One CAMERA track (positions computed by us, yaw/pitch aim at the target each sample)."""
    tg = as_target(target)
    ticks, total = _ticks(start, seconds, samples_per_s)
    mid = (ticks[0] + ticks[-1]) // 2
    # heading from the target's motion around mid-shot (fallback: its facing)
    a, b = tg.pos(max(0, mid - 10)), tg.pos(mid + 10)
    hx, hz = b[0] - a[0], b[2] - a[2]
    if math.hypot(hx, hz) < 0.5:
        yaw = math.radians(tg.rot(mid)[0])
        hx, hz = -math.sin(yaw), math.cos(yaw)
    hl = math.hypot(hx, hz)
    fx, fz = hx / hl, hz / hl                      # forward
    rx, rz = -fz, fx                               # right-hand lateral (x right, z down viewed from above: rotate)
    pm = tg.pos(mid)
    A = (pm[0] + side_sign * side * rx - ahead * fx, pm[1] + height, pm[2] + side_sign * side * rz - ahead * fz)
    B = (pm[0] + side_sign * side * rx + ahead * fx, pm[1] + height, pm[2] + side_sign * side * rz + ahead * fz)
    e = _ease(ease)
    n = len(ticks) - 1
    kfs = {}
    prev_yaw = None
    for i, t in enumerate(ticks):
        u = e(i / n)
        eye = tuple(_lerp(A[k], B[k], u) for k in range(3))
        px, py, pz = tg.pos(t)
        look = (px + look_offset[0], py + look_offset[1], pz + look_offset[2])
        yw = _yaw_to(eye, look)
        if prev_yaw is not None:
            yw = _unwrap(prev_yaw, yw)
        prev_yaw = yw
        kfs[t] = camera_eye_kf(eye, yw, _pitch_to(eye, look))
    return Shot(name or f"flyby@{start}", "flyby", start, ticks[-1], [Track("CAMERA", kfs)],
                "straight fly-by", dict(side=side, height=height, ahead=ahead))


def track_follow(target, start: int, seconds: float = 5.0, distance: float = 4.5, up: float = 0.9,
                 part: str = "BODY", yaw_offset: float = 0.0, pitch_offset: float = 10.0,
                 yaw_offset_end: float | None = None, uuid: str | None = None, name: str | None = None) -> Shot:
    """TRACK_ENTITY chase cam: Flashback itself positions the camera ``distance`` behind the entity every frame
    (so it follows exactly even though we only write 2-3 keyframes). Needs the entity UUID.
    viewOffset z>0 = behind the entity (verified in KeyframeChangeTrackEntity.apply)."""
    tg = as_target(target, uuid)
    if not tg.uuid:
        raise ValueError("track_follow needs the entity uuid")
    total = max(2, int(round(seconds * 20)))
    ticks = _unique([start, start + total // 2, start + total])
    ye = yaw_offset if yaw_offset_end is None else yaw_offset_end
    kfs = {}
    for t in ticks:
        u = (t - start) / total
        kfs[t] = track_entity_kf(tg.uuid, part, _lerp(yaw_offset, ye, u), pitch_offset, (0, 0, 0),
                                 (0, up, distance), 0.0)
    return Shot(name or f"follow@{start}", "track_follow", start, ticks[-1], [Track("TRACK_ENTITY", kfs)],
                f"chase cam d={distance} part={part}", dict(distance=distance, part=part))


def timelapse(target, start: int, end: int, video_seconds: float = 6.0, camera: str = "orbit",
              radius: float = 18.0, height: float = 9.0, revolutions: float = 0.5, name: str | None = None,
              pos=None) -> Shot:
    """Speed-up a long stretch (``end-start`` replay ticks) into ``video_seconds`` of video.

    Track layout: TIMELAPSE keyframes at timeline ticks (start, end) with video ticks (0, video_seconds*20) plus
    a camera track (``orbit`` around the target / ``static`` at ``pos`` looking at the target / ``follow``).
    Camera keyframes are placed in *timeline* ticks, evenly in real time (we convert through the linear
    timelapse mapping) so the orbit finishes exactly when the video does."""
    tg = as_target(target)
    vt = max(2, int(round(video_seconds * 20)))
    span = end - start
    n = max(4, int(math.ceil(video_seconds * 4)))
    to_tl = lambda i: start + int(round(i * span / n))
    kfs = {}
    e = _ease("inout" if camera == "orbit" else "linear")
    y0 = tg.rot(start)[0]
    for i in range(n + 1):
        t = to_tl(i)
        px, py, pz = tg.pos(t)
        c = (px, py + 1.2, pz)
        if camera == "orbit":
            kfs[t] = orbit_kf(c, math.hypot(radius, height), y0 + 360 * revolutions * e(i / n),
                              math.degrees(math.atan2(height, radius)))
        else:
            eye = pos or (px + radius, py + height, pz + radius)
            kfs[t] = camera_eye_kf(eye, _yaw_to(eye, c), _pitch_to(eye, c))
    cam_type = "CAMERA_ORBIT" if camera == "orbit" else "CAMERA"
    tl = {start: timelapse_kf(0), end: timelapse_kf(vt)}
    return Shot(name or f"timelapse@{start}", "timelapse", start, end, [Track("TIMELAPSE", tl), Track(cam_type, kfs)],
                f"{span / 20:.0f}s of game in {video_seconds}s", dict(video_seconds=video_seconds))


TEMPLATES = {"orbit": orbit, "drone_pullup": drone_pullup, "push_in": push_in, "flyby": flyby,
             "track_follow": track_follow, "timelapse": timelapse}


# ---------------------------------------------------------------------------
# Automatic planning: replay -> moments -> shots -> editor state + export job list
# ---------------------------------------------------------------------------
DEFAULT_SHOT_SECONDS = {"orbit": 6.0, "drone_pullup": 5.0, "push_in": 3.5, "flyby": 4.5, "track_follow": 6.0}


def auto_shots(replay, max_shots: int = 8, seconds_scale: float = 1.0, lead_s: float = 1.0) -> list[Shot]:
    """Turn ``replay.suggest_moments()`` into Shot objects around the recording player."""
    from .flashback_replay import Replay  # local import to keep modules decoupled

    assert isinstance(replay, Replay)
    tg = as_target(replay.player_track(), replay.local_uuid)
    shots: list[Shot] = []
    for m in replay.suggest_moments(top=max_shots * 2):
        kind = m["suggested_shot"]
        secs = DEFAULT_SHOT_SECONDS.get(kind, 5.0) * seconds_scale
        start = max(0, int(m["tick"] - lead_s * 20))
        end_cap = replay.total_ticks - 2
        if start + int(secs * 20) > end_cap:
            start = max(0, end_cap - int(secs * 20))
        tag = f"{m['kind']}@{m['tick']}"
        if kind == "orbit":
            s = orbit(tg, start, secs, name=tag)
        elif kind == "drone_pullup":
            s = drone_pullup(tg, start, secs, name=tag)
        elif kind == "push_in":
            s = push_in(tg, start, secs, name=tag)
        elif kind == "flyby":
            s = flyby(tg, start, secs, name=tag)
        elif kind == "track_follow":
            s = track_follow(tg, start, secs, name=tag)
        else:
            continue
        s.note = m["reason"]
        shots.append(s)
        if len(shots) >= max_shots:
            break
    return shots


@dataclass
class ExportOptions:
    """Per-job export settings consumed by the flashback_auto mod (maps 1:1 onto ExportSettings)."""

    width: int = 1920
    height: int = 1080
    fps: float = 60.0
    container: str = "MP4"
    codec: str = "H264"
    encoder: str | None = None        # e.g. "libx264", "h264_amf" (None -> Flashback's first valid encoder)
    bitrate: int = 20_000_000
    ssaa: bool = False
    no_gui: bool = True
    reset_rng: bool = False
    record_audio: bool = False
    transparent: bool = False


def jobs_json(replay_path: str | Path, shots: Sequence[Shot], out_dir: str | Path,
              opts: ExportOptions | None = None, prefix: str = "") -> dict:
    """Job list for the flashback_auto mod: one job per scene/shot, rendered to <out_dir>/<prefix><shot>.mp4."""
    opts = opts or ExportOptions()
    out_dir = Path(out_dir)
    jobs = []
    for i, s in enumerate(shots):
        safe = re.sub(r"[^A-Za-z0-9_.@-]+", "_", f"{prefix}{i:02d}_{s.name}")
        jobs.append({
            "scene": i, "name": safe, "start": s.start, "end": s.end,
            "output": str(out_dir / f"{safe}.{opts.container.lower() if opts.container != 'PNG_SEQUENCE' else 'png'}"),
            "width": opts.width, "height": opts.height, "fps": opts.fps, "container": opts.container,
            "codec": opts.codec, "encoder": opts.encoder, "bitrate": opts.bitrate, "ssaa": opts.ssaa,
            "noGui": opts.no_gui, "resetRng": opts.reset_rng, "recordAudio": opts.record_audio,
            "transparent": opts.transparent, "kind": s.kind, "note": s.note,
        })
    return {"version": 1, "replay": str(replay_path), "jobs": jobs}


# ---------------------------------------------------------------------------
# Self check + CLI
# ---------------------------------------------------------------------------
def selfcheck(verbose: bool = True) -> list[str]:
    """Round-trip + numeric sanity of every template on a synthetic walking target."""
    errs: list[str] = []
    walk = Target(lambda t: (10.0 + 0.2 * t, 64.0, 5.0 + 0.05 * t), lambda t: (-90.0, 5.0),
                  "5bbc695b-1bcf-3837-8441-a51d0fa760a5", "walker")
    shots = [
        orbit(walk, 100, 6.0, radius=6, height=2),
        drone_pullup(walk, 200, 5.0),
        push_in(walk, 300, 3.0, fov_from=70, fov_to=45),
        flyby(walk, 400, 4.0),
        track_follow(walk, 500, 5.0),
        timelapse(walk, 600, 3600, 6.0),
    ]
    st = build_state(shots, Visuals(night_vision=True, time_of_day=18000), "C:/x/replay.zip")
    errs += roundtrip_check(st)
    # orbit: camera must stay at constant horizontal distance + height from the moving centre
    sc = st["scenes"][0]
    for t in range(100, 220, 7):
        pose = camera_pose(sc, t)
        px, py, pz = walk.pos(t)
        (cx, cy, cz), yaw, pitch = pose
        hd = math.hypot(cx - px, cz - pz)
        dh = cy - (py + 1.2)
        if abs(hd - 6.0) > 0.35 or abs(dh - 2.0) > 0.35:
            errs.append(f"orbit @ {t}: horizontal {hd:.2f} (want 6) height {dh:.2f} (want 2)")
    # orbit must look at the centre: look vector * d + cam == centre
    (cx, cy, cz), yaw, pitch = camera_pose(sc, 150)
    px, py, pz = walk.pos(150)
    yr, pr = math.radians(-yaw), math.radians(pitch)
    d = math.dist((cx, cy, cz), (px, py + 1.2, pz))
    la = (cx + math.sin(yr) * math.cos(pr) * d, cy - math.sin(pr) * d, cz + math.cos(yr) * math.cos(pr) * d)
    if math.dist(la, (px, py + 1.2, pz)) > 0.4:
        errs.append("orbit camera does not look at the centre")
    # flyby aims at target
    sc2 = st["scenes"][3]
    (cx, cy, cz), yaw, pitch = camera_pose(sc2, 420)
    px, py, pz = walk.pos(420)
    want_yaw = _yaw_to((cx, cy, cz), (px, py + 1.2, pz))
    if abs(_wrap180(yaw - want_yaw)) > 2.0:
        errs.append(f"flyby yaw {yaw:.1f} != aim {want_yaw:.1f}")
    # track_follow: camera ends up `distance` behind the player along its facing
    kf = st["scenes"][4]["keyframeTracks"][0]["keyframesByTick"]["500"]
    eye, y, p = track_entity_eye(walk.pos(500), -90.0, 5.0, kf)
    behind = math.hypot(eye[0] - walk.pos(500)[0], eye[2] - walk.pos(500)[2])
    if abs(behind - 4.5) > 0.2:
        errs.append(f"track_follow offset {behind:.2f} != 4.5")
    # timelapse speed: (3600-600)/(120-0)*20 = 500 ticks/s
    tl = st["scenes"][5]["keyframeTracks"][0]["keyframesByTick"]
    sp = (3600 - 600) / (tl["3600"]["ticks"] - tl["600"]["ticks"]) * 20
    if abs(sp - 500.0) > 1e-6:
        errs.append(f"timelapse speed {sp}")
    # negative tests: the validator must reject broken input
    bad = copy.deepcopy(st)
    bad["scenes"][0]["keyframeTracks"][0]["keyframesByTick"]["100"]["center"] = [1, 2]
    bad["scenes"][1]["keyframeTracks"][0]["enabled"] = None
    bad["scenes"][2]["keyframeTracks"][0]["keyframesByTick"]["300"]["type"] = "camera"
    if len(validate_state(bad)) < 3:
        errs.append("validator failed to catch deliberately broken state")
    if verbose:
        print("selfcheck:", "OK" if not errs else errs)
    return errs


def _main(argv=None):
    import argparse
    from . import flashback_replay as fr

    ap = argparse.ArgumentParser(description="Plan cinematic shots for a Flashback replay and emit editor state")
    ap.add_argument("replay", nargs="?")
    ap.add_argument("--out", default=None, help="directory for <uuid>.json and jobs.json (default: ./flashback_out)")
